type AdvancedLevel = 'n2' | 'n1';
type Choice = [text: string, explanation: string];
type FourChoices = [Choice, Choice, Choice, Choice];
export const datasetAdvancedVocabulary: Vocabulary[] = [];
export const datasetAdvancedGrammar: Grammar[] = [];
export const datasetAdvancedReadings: Reading[] = [];
export const datasetAdvancedListening: Listening[] = [];
export const datasetAdvancedQuestions: Question[] = [];

function question(level: AdvancedLevel, slug: string, skill: Question['skill'], topicId: TopicId, questionType: QuestionType, prompt: string, choices: FourChoices, links: Partial<Question>): string {
  const id = `ds-q-${level}-${slug}`;
  const shift = [...id].reduce((sum, c) => sum + c.charCodeAt(0), 0) % 4;
  const ordered = [...choices.slice(shift), ...choices.slice(0, shift)];
  const options = ordered.map(([text], i) => ({ id: `${id}-${'abcd'[i]}`, text }));
  datasetAdvancedQuestions.push({ id, skill, topicId, jlptLevel: level, questionType, prompt, options,
    correctOptionId: options[ordered.indexOf(choices[0])].id,
    explanations: Object.fromEntries(ordered.map((choice, i) => [options[i].id, choice[1]])), ...links });
  return id;
}

