for (const level of ['n2', 'n1'] as const) {
  words[level].forEach(([word, reading, meaning, wordClass, example, exampleTranslation, topicId], i) => {
    if (!example.includes(word)) throw new Error(`${level} ${word}: the example must include the exact spelling.`);
    datasetAdvancedVocabulary.push({ id: `ds-v-${level}-${String(i + 1).padStart(3, '0')}`, word, reading, meaning, wordClass, example, exampleTranslation, topicId, jlptLevel: level, level: 'extension' });
  });
}

type Exercise = { prompt: string; choices: FourChoices; questionType?: QuestionType };
function lesson(level: AdvancedLevel, slug: string, title: string, meaning: string, attachment: string[], topicId: TopicId, category: string, comparison: string, examples: Grammar['examples'], mistake: Grammar['mistake'], exercises: [Exercise, Exercise]): void {
  const id = `ds-g-${level}-${slug}`;
  const questionIds = exercises.map((ex, i) => question(level, `g-${slug}-${i + 1}`, 'grammar', topicId, ex.questionType || 'grammar-form', ex.prompt, ex.choices, { grammarId: id }));
  datasetAdvancedGrammar.push({ id, title, meaning, attachment, topicId, category, comparison, examples, mistake, questionIds, jlptLevel: level, level: 'extension' });
}

type SourceExercise = Exercise & { evidence: string };
function source(kind: 'reading' | 'listening', level: AdvancedLevel, slug: string, title: string, topicId: TopicId, text: string, translation: string, exercises: [SourceExercise, SourceExercise], type: Reading['type'] = 'article'): void {
  const id = `ds-${kind === 'reading' ? 'r' : 'l'}-${level}-${slug}`;
  const questionIds = exercises.map((ex, i) => {
    if (!text.includes(ex.evidence)) throw new Error(`${id}: evidence does not occur literally in its source.`);
    return question(level, `${kind === 'reading' ? 'r' : 'l'}-${slug}-${i + 1}`, kind, topicId, ex.questionType || (kind === 'reading' ? 'reading-medium' : 'listening-points'), ex.prompt, ex.choices,
      { ...(kind === 'reading' ? { passageId: id } : { listeningId: id }), evidence: `「${ex.evidence}」` });
  });
  if (kind === 'reading') datasetAdvancedReadings.push({ id, title, body: text, translation, topicId, type, questionIds, jlptLevel: level });
  else datasetAdvancedListening.push({ id, title, script: text, translation, topicId, questionIds, jlptLevel: level });
}

lesson('n2','without-interruption','～ことなく','Do the following action without performing or undergoing the first. This is a written or formal alternative to ～ないで.',['Dictionary verb + ことなく.','Use it for an omitted action or an uninterrupted process; do not attach it directly to a noun.'],'education','manner','～ずに is also “without doing.” ～ことなく is more formal; it does not mean never having had an experience, which is ～たことがない.',[
  {ja:'彼女は諦めることなく、別の解決方法を探し続けた。',en:'She continued searching for another solution without giving up.'},
  {ja:'資料の内容を変えることなく、見出しだけを整理した。',en:'We reorganized only the headings without changing the contents of the materials.'},
],{wrong:'彼女は諦めたことなく、別の解決方法を探し続けた。',correct:'彼女は諦めることなく、別の解決方法を探し続けた。',explanation:'This connector takes the dictionary form 諦める. 諦めたことがない would instead describe lack of a past experience.'},[
  {prompt:'「内容を変えずに」という意味にしてください。資料の内容を変える（　）、見出しだけを整理した。',choices:[['ことなく','Dictionary verb + ことなく expresses not changing the contents while reorganizing the headings.'],['ことで','ことで would make changing the contents the means of reorganizing, contradicting the instruction.'],['ことから','ことから presents a reason or inference from changing the contents, not omission of that action.'],['ことに','ことに does not form the “without doing” connector after 変える.']]},
  {prompt:'「諦めることなく、別の解決方法を探し続けた」とは、どういうことですか。',choices:[['諦めずに、ほかの方法を探し続けた。','The first action is omitted while the search continues.'],['諦めた後で、探すのもやめた。','The sentence says the search continued and no giving up occurred.'],['探す前に、解決方法を全て変えた。','Neither changing all methods nor that sequence is stated.'],['諦めた経験が一度もないと自慢した。','This is not the experiential pattern ～たことがない and contains no boasting.']]},
]);

lesson('n2','on-occasion','～にあたって','Introduce preparations or considerations when beginning a significant activity or reaching an important occasion.',['Noun / dictionary verb + にあたって.','Noun modification: ～にあたっての + noun. Formal; typical with starts, decisions and major occasions.'],'work','occasion','～とき is general. ～にあたって frames an important occasion and its preparation; it is usually less natural for an accidental mishap than the broader ～に際して.',[
  {ja:'新しい事業を始めるにあたって、地域の需要を調べた。',en:'Before starting the new business, we investigated local demand.'},
  {ja:'卒業にあたって、支えてくれた人々に感謝を伝えたい。',en:'On the occasion of graduation, I want to thank those who supported me.'},
],{wrong:'新しい事業を始めたにあたって、地域の需要を調べた。',correct:'新しい事業を始めるにあたって、地域の需要を調べた。',explanation:'Use the dictionary form 始める before にあたって; the final past predicate 調べた places the overall event in the past.'},[
  {prompt:'新しい事業を（　）にあたって、地域の需要を調べた。',choices:[['始める','にあたって attaches to the dictionary verb even in a past narrative.'],['始めた','The past form is not the attachment used with this occasion connector.'],['始めて','A て-form does not directly attach to にあたって.'],['始めます','The polite ending belongs on the final predicate rather than before にあたって.']]},
  {prompt:'「卒業にあたって、感謝を伝えたい」の意味に最も近いものはどれですか。',choices:[['卒業という大切な機会に、感謝を伝えたい。','The construction marks graduation as the occasion for expressing thanks.'],['感謝を伝えたせいで、卒業できなくなった。','No adverse cause or failure to graduate is expressed.'],['卒業してから何年も、感謝を伝え続けたい。','The construction gives an occasion, not a years-long duration.'],['感謝を伝えれば、必ず卒業できる。','This is not a condition guaranteeing graduation.']]},
]);

lesson('n2','prior-to','～に先立って','Perform a preparation before a main event. It establishes an advance sequence in formal language.',['Noun / dictionary verb + に先立って.','Noun + に先立つ + noun modifies a preparatory activity.'],'community','sequence','～前に is neutral everyday language. ～に先立って commonly marks a planned preparatory stage before a notable event.',[
  {ja:'工事に先立って、近隣の住民への説明会を開いた。',en:'Before construction, we held an information meeting for nearby residents.'},
  {ja:'調査を実施するに先立って、質問の分かりやすさを確かめた。',en:'Before conducting the survey, we checked whether the questions were easy to understand.'},
],{wrong:'工事を先立って、近隣の住民への説明会を開いた。',correct:'工事に先立って、近隣の住民への説明会を開いた。',explanation:'The upcoming event takes に in the fixed expression に先立って, rather than the object particle を.'},[
  {prompt:'工事（　）、近隣の住民への説明会を開いた。工事より先に説明したという意味です。',choices:[['に先立って','に先立って places the explanation meeting before construction.'],['を通じて','を通じて means through construction, not before it.'],['にわたって','にわたって expresses an extent or period, not a preparatory sequence.'],['に先立つを','に先立つ is a noun modifier; adding を does not connect these clauses.']]},
  {prompt:'「調査を実施するに先立って、質問を確かめた」では、何を先にしましたか。',choices:[['質問が分かりやすいか確認した。','The check precedes the survey.'],['調査の結果を発表した。','No results have been gathered or announced in this sentence.'],['調査を全て終えた。','The survey is the later event, not the completed prerequisite.'],['調査の対象を減らした。','Changing the surveyed population is not stated.']]},
]);

lesson('n2','accompanying-change','～に伴って','Describe a change or action that accompanies another change. The relationship may be causal or closely associated.',['Noun / dictionary verb + に伴って.','Noun modification: ～に伴う + noun. Formal explanations often pair two developments.'],'community','change','～につれて emphasizes gradual linked change. ～に伴って can also describe consequences of a single institutional change, and does not itself prove that both changes are beneficial.',[
  {ja:'人口の増加に伴って、保育施設への需要も高まった。',en:'Demand for childcare facilities grew along with population growth.'},
  {ja:'勤務制度が変わるに伴って、連絡の方法も見直す必要がある。',en:'As the work arrangements change, communication methods also need revision.'},
],{wrong:'人口の増加を伴って、保育施設への需要も高まった。（増加に合わせて需要が変化したという意味）',correct:'人口の増加に伴って、保育施設への需要も高まった。',explanation:'For the change used as the reference, use に伴って. ～を伴って is a different transitive pattern meaning “with/accompanied by,” with a different relationship.'},[
  {prompt:'人口が増えるのと関連して需要も高まった。人口の増加（　）、保育施設への需要も高まった。',choices:[['に伴って','The population increase is the reference change accompanying increased demand.'],['に反して','に反して would say demand rose contrary to population growth rather than alongside it.'],['にもかかわらず','This would frame growth as an obstacle unexpectedly overcome, contrary to the stated association.'],['に限らず','に限らず extends a category beyond population growth, rather than expressing linked change.']]},
  {prompt:'「勤務制度が変わるに伴って、連絡の方法も見直す必要がある」と述べる人の考えはどれですか。',choices:[['勤務制度の変更に合わせ、連絡方法も検討し直すべきだ。','The second adjustment accompanies the first institutional change.'],['連絡方法さえ変えれば、勤務制度は変わらない。','No condition preventing the work change is stated.'],['勤務制度とは無関係に、連絡だけを減らすべきだ。','The construction explicitly links the changes; reducing contact is not stated.'],['勤務制度が変わったので、連絡は全て不要だ。','Revising communication methods does not mean eliminating communication.']]},
]);

lesson('n2','following-guideline','～に沿って','Proceed in accordance with a plan, wishes, policy or other guiding reference. A separate spatial use means along a line.',['Noun + に沿って.','Noun modifier: ～に沿った + noun. This lesson practices the guideline use.'],'work','accordance','～に基づいて stresses the basis for a decision; ～に沿って stresses following an intended direction or guideline in carrying something out.',[
  {ja:'利用者の希望に沿って、開館時間を調整した。',en:'We adjusted opening hours in line with users’ wishes.'},
  {ja:'計画に沿った実施が難しい場合は、理由を報告する。',en:'If implementing the plan as intended is difficult, report the reasons.'},
],{wrong:'利用者の希望を沿って、開館時間を調整した。',correct:'利用者の希望に沿って、開館時間を調整した。',explanation:'The guiding reference takes に; 希望 is not a direct object marked by を here.'},[
  {prompt:'希望に合わせて調整したという意味にしてください。利用者の希望（　）、開館時間を調整した。',choices:[['に沿って','希望に沿って means following users’ wishes.'],['に反して','に反して means contrary to their wishes.'],['を問わず','を問わず would disregard the wishes rather than use them as a guide.'],['に沿った','沿った modifies a following noun and cannot directly connect this clause.']]},
  {prompt:'「計画に沿った実施が難しい場合は、理由を報告する」という指示に合う行動はどれですか。',choices:[['計画どおりに進められないとき、その理由を伝える。','The instruction requires an explanation when following the plan is difficult.'],['計画を守れないとき、何も知らせずに変更する。','The instruction specifically asks for a report of reasons.'],['計画どおりでも、必ず事業を中止する。','Following the plan does not trigger cancellation.'],['理由を報告すれば、計画そのものは常に不要になる。','Reporting difficulty does not automatically remove the need for a plan.']]},
]);

lesson('n2','contrary-to','～に反して','Describe a result or behavior contrary to an expectation, intention, prediction or rule.',['Noun + に反して.','Noun modifier: ～に反する / ～に反した + noun. Formal or neutral written expression.'],'communication','contrast','～と違って simply distinguishes two things. ～に反して states that one outcome or action goes against a particular reference or expectation.',[
  {ja:'予想に反して、説明を短くしたほうが質問が増えた。',en:'Contrary to expectations, shortening the explanation led to more questions.'},
  {ja:'本人の意向に反した変更は、後の対立につながりやすい。',en:'Changes contrary to the person’s wishes can lead to later conflict.'},
],{wrong:'予想を反して、質問が増えた。',correct:'予想に反して、質問が増えた。',explanation:'Use に to mark the expectation being contradicted; 反する is not transitive with を in this construction.'},[
  {prompt:'予想とは逆の結果だった。予想（　）、説明を短くしたほうが質問が増えた。',choices:[['に反して','The result contradicted the prediction.'],['に従って','に従って means following the prediction, opposite to the stated result.'],['に基づいて','に基づいて would make the prediction a basis for action, not an expectation contradicted by a result.'],['に限って','に限って restricts the situation and does not state opposition to an expectation.']]},
  {prompt:'「本人の意向に反した変更」とはどのような変更ですか。',choices:[['本人が望んでいる方向とは違う変更。','The change goes against the person’s wishes.'],['本人の望みをそのまま実現する変更。','That would be 意向に沿った, the opposite relationship.'],['本人の意向が全く分からないため、行わなかった変更。','No inability to know the intention or cancellation is expressed.'],['本人以外は誰も知ることのできない変更。','The pattern concerns disagreement with wishes, not secrecy.']]},
]);

lesson('n2','now-that','～以上は','Treat an established fact or commitment as a basis for an obligation, determination or expected conclusion.',['Verb / い-adjective plain form + 以上は.','Noun / な-adjective + である以上は. The second clause commonly gives responsibility, resolve or a judgment.'],'work','reasoning','～から is a general reason. ～以上は emphasizes that accepting the premise commits one to a corresponding responsibility or consequence; it is not a temporal “after.”',[
  {ja:'引き受けた以上は、最後まで責任を持って進めたい。',en:'Now that I have accepted it, I want to see it through responsibly.'},
  {ja:'公開する資料である以上は、出典を明記すべきだ。',en:'Since these materials will be made public, their sources should be specified.'},
],{wrong:'公開する資料だ以上は、出典を明記すべきだ。',correct:'公開する資料である以上は、出典を明記すべきだ。',explanation:'A noun uses the formal copular connection である以上は, not だ以上は.'},[
  {prompt:'公開する資料（　）、出典を明記すべきだ。',choices:[['である以上は','The noun 資料 takes である before 以上は, establishing a reason for responsibility.'],['だ以上は','The noun connection is である以上は.'],['な以上は','な is not the noun connection used in this construction.'],['を以上は','The object particle cannot connect a noun to this premise expression.']]},
  {prompt:'「引き受けた以上は、最後まで責任を持って進めたい」の話し手の考えはどれですか。',choices:[['引き受けたことに伴う責任を果たしたい。','Acceptance is the premise for a commitment to finish responsibly.'],['引き受けたので、もう何もする必要がない。','This reverses the responsibility emphasized by the sentence.'],['最後まで終えた後なら、引き受けてもよい。','The sentence establishes acceptance first, not completion as a prerequisite.'],['引き受けた経験はあるが、今回は断る。','The sentence expresses resolve concerning an accepted task, not refusal.']]},
]);

lesson('n2','after-deliberation','～末に','Describe a result reached after a substantial process of deliberation, effort or difficulty.',['Verb た-form + 末に.','Process noun + の末に. The result may be good or bad; the expression emphasizes the preceding process.'],'communication','sequence','～後で merely orders events. ～末に highlights the extended process; ～あげく typically adds an undesirable outcome.',[
  {ja:'何度も話し合った末に、両方の案を試すことになった。',en:'After repeated discussions, we decided to try both proposals.'},
  {ja:'長い検討の末に、当初の計画を縮小した。',en:'After lengthy consideration, we scaled down the original plan.'},
],{wrong:'何度も話し合う末に、両方の案を試すことになった。',correct:'何度も話し合った末に、両方の案を試すことになった。',explanation:'The process is completed before the resulting decision, so use the verb’s た-form before 末に.'},[
  {prompt:'何度も（　）末に、両方の案を試すことになった。',choices:[['話し合った','た-form + 末に expresses the completed deliberation leading to a result.'],['話し合う','The dictionary form does not mark the completed process in this result pattern.'],['話し合って','The て-form does not attach directly to 末に.'],['話し合いです','A polite copula does not connect the process to 末に.']]},
  {prompt:'「長い検討の末に、計画を縮小した」が特に強調することは何ですか。',choices:[['縮小を決めるまでに、長く検討した。','末に draws attention to the substantial process before the outcome.'],['縮小は必ず失敗だった。','The expression allows both good and bad results; failure is not entailed.'],['検討せず、すぐに縮小を決めた。','This contradicts 長い検討 and the process emphasis.'],['縮小した後で初めて検討を始めた。','The order is reversed: deliberation precedes the scaling down.']]},
]);

lesson('n2','unfortunate-end','～あげく','Describe an undesirable result after a prolonged process, trouble or effort.',['Verb た-form + あげく（に）.','Process noun + のあげく（に）. Usually carries disappointment or criticism.'],'feelings','sequence','～末に can introduce a positive resolution. ～あげく usually presents the effort or trouble as ending badly; use a positive-result pattern for ordinary praise.',[
  {ja:'散々迷ったあげく、申し込みの期限を過ぎてしまった。',en:'After wavering endlessly, I ended up missing the application deadline.'},
  {ja:'長い議論のあげく、何も決まらずに会議が終わった。',en:'After a lengthy argument, the meeting ended without any decision.'},
],{wrong:'散々迷うあげく、申し込みの期限を過ぎてしまった。',correct:'散々迷ったあげく、申し込みの期限を過ぎてしまった。',explanation:'Use the completed た-form 迷った for the process leading to the adverse outcome.'},[
  {prompt:'長い議論（　）、何も決まらずに会議が終わった。',choices:[['のあげく','The noun 議論 takes の; the disappointing result fits あげく.'],['なあげく','議論 is a noun and takes の, not adjective な.'],['をあげく','The object particle does not attach a process noun to あげく.'],['であげく','The standard process-noun connection is のあげく.']]},
  {prompt:'「散々迷ったあげく、期限を過ぎてしまった」という話し手は、結果をどう捉えていますか。',choices:[['長く迷ったのに、望ましくない結果になった。','あげく and しまった present a disappointing endpoint after trouble.'],['迷ったおかげで、理想どおりに申し込めた。','Missing the deadline is the adverse result, not a successful application.'],['期限を過ぎることを最初から目標にしていた。','The sentence conveys regret, not a planned goal.'],['迷った時間と結果には全く関係がない。','The construction explicitly links the prolonged hesitation to the outcome.']]},
]);

lesson('n2','as-expected-of','～だけあって','Explain a fitting, usually favorable result by a person’s ability, status or another noteworthy quality.',['Verb / い-adjective plain form + だけあって.','Noun + だけあって; な-adjective + なだけあって. Often conveys appreciation that the result lives up to expectations.'],'people','evaluation','～だけに can emphasize a reason even for disappointment. ～だけあって commonly praises a result that is appropriate to the noted quality; it is more than mere quantity limitation.',[
  {ja:'長年教えているだけあって、説明が分かりやすい。',en:'As expected of someone who has taught for years, her explanations are clear.'},
  {ja:'経験豊富なだけあって、急な変更にも落ち着いて対応した。',en:'As expected of someone experienced, he handled the sudden change calmly.'},
],{wrong:'経験豊富のだけあって、急な変更にも落ち着いて対応した。',correct:'経験豊富なだけあって、急な変更にも落ち着いて対応した。',explanation:'経験豊富 is a な-adjectival expression; use な, rather than の, before だけあって.'},[
  {prompt:'経験豊富（　）、急な変更にも落ち着いて対応した。',choices:[['なだけあって','A な-adjective takes な; the calm response fits the expected benefit of experience.'],['のだけあって','の is not the な-adjective connection before だけあって.'],['をだけあって','を cannot connect the adjectival quality to this evaluative expression.'],['でだけあって','The standard な-adjective connection is なだけあって.']]},
  {prompt:'「長年教えているだけあって、説明が分かりやすい」の意味はどれですか。',choices:[['長い指導経験にふさわしく、説明が上手だ。','The clear explanation lives up to the expectation created by long experience.'],['長く教えているのに、説明が全く伝わらない。','That is an unfavorable contrast, opposite to the stated evaluation.'],['教えた年数だけを数え、説明の質は評価しない。','The sentence explicitly evaluates the clarity of the explanation.'],['説明が分かりやすければ、経験は必ず長い。','The sentence gives a reason for this result, not a universal reverse implication.']]},
]);

lesson('n1','first-in-series','～を皮切りに','Mark the first event that launches a sequence or expansion of similar events.',['Event noun + を皮切りに（して）.','Often used in reports of a tour, rollout or growing series; not merely the first step in any unrelated sequence.'],'culture','sequence','～を始めとして can list a representative item. ～を皮切りに specifically presents a starting event followed by further developments.',[
  {ja:'東京での公演を皮切りに、各地で同じ劇を上演した。',en:'Beginning with the Tokyo performance, they staged the same play in various places.'},
  {ja:'一校での試行を皮切りに、新しい教材の導入が広がった。',en:'Starting with a trial at one school, adoption of the new materials spread.'},
],{wrong:'東京での公演に皮切りに、各地で同じ劇を上演した。',correct:'東京での公演を皮切りに、各地で同じ劇を上演した。',explanation:'The first event is marked with を in the fixed expression を皮切りに.'},[
  {prompt:'東京での公演（　）、各地で同じ劇を上演した。東京が一連の公演の出発点だった。',choices:[['を皮切りに','The first performance launches a series of later performances.'],['をよそに','をよそに means disregarding or being unaffected by something, not launching a series.'],['にひきかえ','にひきかえ contrasts the Tokyo event with something else; it does not mark the starting point.'],['を限りに','を限りに marks an endpoint, opposite to the start of the series.']]},
  {prompt:'「一校での試行を皮切りに、導入が広がった」から読み取れることはどれですか。',choices:[['一校の試行が最初で、その後ほかにも導入された。','The trial serves as the opening event of expanding adoption.'],['全校で同時に試行し、その後一校だけ残した。','This reverses the expansion from a single initial school.'],['一校で失敗したため、どこにも導入されなかった。','The sentence explicitly states that adoption spread.'],['一校での試行と導入の広がりは、時間的に無関係だ。','The construction identifies the trial as the beginning of the sequence.']]},
]);

lesson('n1','disregarding-concern','～をよそに','Describe conduct that ignores or remains unaffected by surrounding concern, criticism, expectations or commotion.',['Noun + をよそに.','Usually contrasts the surroundings with a person’s conduct; often implies the observer’s surprise or disapproval.'],'people','contrast','～にもかかわらず is a broad concession. ～をよそに highlights a detached attitude or unaffected course of action in the face of others’ concern.',[
  {ja:'周囲の心配をよそに、彼は一人で旅に出た。',en:'Ignoring the concern around him, he set out on a trip alone.'},
  {ja:'厳しい批判をよそに、責任者は従来の方針を続けた。',en:'Unmoved by harsh criticism, the person in charge continued the previous policy.'},
],{wrong:'周囲の心配によそに、彼は一人で旅に出た。',correct:'周囲の心配をよそに、彼は一人で旅に出た。',explanation:'The concern set aside takes を; によそに does not form this expression.'},[
  {prompt:'周囲の心配（　）、彼は一人で旅に出た。心配されても気にしない様子を表してください。',choices:[['をよそに','The trip proceeds as if the surrounding concern does not affect him.'],['に応じて','に応じて would make his action respond to the concern.'],['に沿って','に沿って would mean following the concern as guidance rather than disregarding it.'],['を込めて','を込めて means putting a feeling into an action and does not express ignoring others’ concern.']]},
  {prompt:'「厳しい批判をよそに、従来の方針を続けた」に最も近い説明はどれですか。',choices:[['批判に左右される様子を見せず、同じ方針を続けた。','The construction depicts conduct unaffected by surrounding criticism.'],['批判を受け入れ、方針を大きく変更した。','This contradicts continuing the previous policy.'],['批判がなくなったので、初めて方針を決めた。','Neither disappearance of criticism nor a first policy decision is stated.'],['批判が正しいと正式に認めた。','Continuing despite criticism does not establish acceptance of its validity.']]},
]);

lesson('n1','sharp-comparison','～にひきかえ','Emphasize a sharp contrast between two comparable people, times or circumstances, often evaluatively.',['Noun + にひきかえ.','A clause can be nominalized with の before にひきかえ: 忙しいのにひきかえ. Noun modification: ～にひきかえた + noun is not the usual comparison pattern.'],'communication','comparison','～一方で can neutrally present two aspects. ～にひきかえ highlights a striking contrast and often the speaker’s assessment of the difference.',[
  {ja:'前回の曖昧な説明にひきかえ、今回は条件が明確に示された。',en:'In sharp contrast to the vague previous explanation, the conditions were clearly stated this time.'},
  {ja:'昼間はにぎやかなのにひきかえ、夜の通りは静まり返っていた。',en:'In sharp contrast to the lively daytime, the street was completely quiet at night.'},
],{wrong:'前回の説明をひきかえ、今回は条件が明確に示された。',correct:'前回の説明にひきかえ、今回は条件が明確に示された。',explanation:'Mark the comparison reference with に in にひきかえ.'},[
  {prompt:'前回の曖昧な説明（　）、今回は条件が明確に示された。前回との鮮やかな対照を表してください。',choices:[['にひきかえ','The vague and clear explanations form a sharp comparison.'],['を皮切りに','This would launch a series of explanations rather than compare their qualities.'],['に加えて','This means addition and does not express the contrast between vague and clear.'],['を通じて','This presents the earlier explanation as a means, not a contrasting reference.']]},
  {prompt:'「昼間はにぎやかなのにひきかえ、夜は静かだ」は何を強調していますか。',choices:[['同じ場所の昼と夜の様子が、はっきり異なる。','The two comparable times show a pronounced contrast.'],['昼も夜も同じくらいにぎやかだ。','This erases the contrast explicitly expressed.'],['夜が静かなことが、昼のにぎやかさの原因だ。','Comparison does not establish this causal relationship.'],['昼と夜のどちらが先か分からない。','The construction contrasts qualities, not the order of day and night.']]},
]);

lesson('n1','alongside-occupation','～かたわら','Carry on a secondary, ongoing activity alongside a main occupation or activity.',['Dictionary verb + かたわら.','Activity noun + のかたわら. Formal; typically a sustained combination of roles rather than two momentary physical actions.'],'work','simultaneity','～ながら can describe simultaneous momentary actions. ～かたわら often spans a period during which a main occupation and a second activity coexist; the literal noun 傍ら also means “beside.”',[
  {ja:'会社で働くかたわら、地域の歴史を調べている。',en:'Alongside working at a company, she studies local history.'},
  {ja:'研究のかたわら、子供向けの科学教室を開いている。',en:'Alongside his research, he runs science classes for children.'},
],{wrong:'研究なかたわら、子供向けの科学教室を開いている。',correct:'研究のかたわら、子供向けの科学教室を開いている。',explanation:'An activity noun takes の; な would be the wrong attachment.'},[
  {prompt:'研究（　）、子供向けの科学教室を開いている。',choices:[['のかたわら','The noun connection is のかたわら; both are sustained activities.'],['なかたわら','研究 is a noun and does not take な here.'],['をかたわら','The object particle does not connect the main activity to かたわら.'],['でかたわら','The standard connection for an activity noun is のかたわら.']]},
  {prompt:'「会社で働くかたわら、地域の歴史を調べている」の意味はどれですか。',choices:[['仕事を続けながら、別の活動として歴史の研究もしている。','The main job coexists over time with a secondary research activity.'],['仕事を完全にやめてから、研究だけを始めた。','かたわら presents coexistence, not abandoning the main occupation.'],['会社の隣の建物でしか、研究してはいけない。','This sentence uses the activity connector, not the literal spatial noun “beside.”'],['働くたびに、必ず同じ一分間だけ歴史を読む。','No exact duration or each-time rule is expressed.']]},
]);

lesson('n1','covered-in','～まみれ','Be covered or soiled with an unwanted substance; figuratively, be full of undesirable things.',['Substance noun + まみれ; predicate ～まみれだ.','Noun modification: ～まみれの + noun. Common with 泥、汗、血、ほこり; use figurative examples carefully.'],'daily','state','～だらけ points to many undesirable things present. ～まみれ especially evokes being coated or smeared with a substance; it is unsuitable for ordinary positive abundance.',[
  {ja:'雨の中で作業し、靴が泥まみれになった。',en:'After working in the rain, my shoes became covered in mud.'},
  {ja:'汗まみれの作業着を着替えてから、会議に参加した。',en:'I changed out of my sweat-soaked work clothes before joining the meeting.'},
],{wrong:'泥にまみれの靴を洗った。',correct:'泥まみれの靴を洗った。',explanation:'For the suffix pattern, attach まみれ directly to the noun: 泥まみれの. The related verb construction is 泥にまみれた靴, with its own verb ending.'},[
  {prompt:'雨の中で作業し、靴が（　）になった。靴全体に泥が付いたという意味です。',choices:[['泥まみれ','泥まみれ describes being coated with mud.'],['泥ずくめ','ずくめ describes things uniformly of one type; it does not naturally describe a coating of mud here.'],['泥ながら','ながら is not a suffix meaning coated in a substance.'],['泥のみならず','のみならず means not only and requires an additional element, not a soiled state.']]},
  {prompt:'「汗まみれの作業着」の状態に最も近いものはどれですか。',choices:[['汗がたくさん染みて、汚れた作業着。','まみれ evokes an unwanted coating or soaking; here the clothes are covered with sweat.'],['汗が一滴も付いていない作業着。','This is the opposite of the described state.'],['汗をかかないために作られた道具。','The phrase describes clothing’s current state, not a tool’s purpose.'],['汗という名前の店で売る新品。','The compound uses the substance sweat, not a shop name.']]},
]);

lesson('n1','uniform-abundance','～ずくめ','Describe something consisting entirely of a particular kind of matter or event, often a collection of favorable events or uniform restrictions.',['Noun + ずくめ; noun modification ～ずくめの + noun.','Common combinations include いいことずくめ、規則ずくめ. This is a fixed suffix, distinct from ～づくり.'],'feelings','state','～だらけ often highlights unwanted scattered items or errors. ～ずくめ emphasizes uniformity or an entire sequence; favorable いいことずくめ is natural, while the substance-coating use favors ～まみれ.',[
  {ja:'今週は友人との再会や合格の知らせなど、いいことずくめだった。',en:'This week was full of good things, including a reunion with a friend and news of passing an exam.'},
  {ja:'規則ずくめの生活では、自分で判断する機会が少ない。',en:'In a life governed entirely by rules, there are few opportunities to make one’s own judgments.'},
],{wrong:'いいことにずくめの一週間だった。',correct:'いいことずくめの一週間だった。',explanation:'The suffix attaches directly to the noun; do not insert に before ずくめ.'},[
  {prompt:'うれしい出来事が続いた。今週は、いいこと（　）だった。',choices:[['ずくめ','いいことずくめ naturally describes a week filled with favorable events.'],['まみれ','まみれ usually describes being soiled with an unwanted substance and does not fit ordinary praise of good events.'],['をよそに','This connector requires a following action and describes disregarding something.'],['にひきかえ','This comparison connector requires a contrasting element rather than forming a predicate of abundance.']]},
  {prompt:'「規則ずくめの生活では、自分で判断する機会が少ない」の意味はどれですか。',choices:[['何でも規則で決まっているため、自分で決める場面が少ない。','Uniform rule-governed conditions restrict opportunities for independent judgment.'],['規則が全くないので、自分で何も考えない。','ずくめ indicates an abundance of rules, not their absence.'],['自分で決める機会が多いほど、必ず規則も増える。','The sentence gives no such universal relationship.'],['規則を作る仕事だけを、長年続けている。','This describes a life filled with rules, not a particular occupation.']]},
]);

lesson('n1','regardless-either','～であれ','Express a formal concession: regardless of being the stated case. Repeated ～であれ～であれ covers alternatives.',['Noun + であれ.','Noun A + であれ、noun B + であれ. Formal writing or statements of principle.'],'community','concession','～でも gives an everyday concession. ～であれ is formal and often asserts a rule across categories; it is not ordinary polite ～であります.',[
  {ja:'専門家であれ、初めての利用者であれ、安全説明は受ける必要がある。',en:'Whether an expert or a first-time user, everyone must receive the safety explanation.'},
  {ja:'小さな変更であれ、その理由を記録しておくべきだ。',en:'Even a small change should have its reasons recorded.'},
],{wrong:'小さな変更だあれ、その理由を記録しておくべきだ。',correct:'小さな変更であれ、その理由を記録しておくべきだ。',explanation:'The fixed concessive form is であれ; だあれ does not form it.'},[
  {prompt:'専門家（　）、初めての利用者（　）、安全説明は受ける必要がある。同じものを入れてください。',choices:[['であれ','Repeated であれ covers both categories under the same requirement.'],['だからこそ','This would make each status a special reason rather than state a rule regardless of status.'],['をよそに','The categories cannot take this connector as predicates of concessive status.'],['に先立って','This would treat statuses as upcoming events and does not create the required concession.']]},
  {prompt:'「小さな変更であれ、理由を記録すべきだ」が認めていないことはどれですか。',choices:[['変更が小さいという理由だけで、記録を省くこと。','Even small changes are included, so size alone does not excuse omitting the reason.'],['小さな変更の理由を記録すること。','This is precisely the action the sentence recommends.'],['大きな変更にも理由があること。','The sentence does not deny reasons for larger changes.'],['変更の大きさが異なること。','The concession allows differences in size while imposing the requirement.']]},
]);

lesson('n1','unworthy-of-status','～ともあろうものが','Criticize conduct as unworthy of someone with a respected role, skill or status.',['Person / status noun + ともあろうものが.','Usually followed by reproach for actual behavior; strong and unsuitable for a neutral polite request.'],'people','evaluation','～でさえ neutrally includes an unexpected case. ～ともあろうものが specifically invokes high expectations and disappointment about the person’s conduct.',[
  {ja:'責任者ともあろうものが、確認せずに噂を広めた。',en:'Someone who should know better as the person in charge spread a rumor without checking it.'},
  {ja:'教師ともあろうものが、質問した学生を笑うとは情けない。',en:'It is deplorable for someone who is a teacher to laugh at a student for asking a question.'},
],{wrong:'責任者ともあろうものを、確認せずに噂を広めた。',correct:'責任者ともあろうものが、確認せずに噂を広めた。',explanation:'The person behaving unworthily is marked by が in this fixed reproachful expression.'},[
  {prompt:'責任者（　）、確認せずに噂を広めた。役割にふさわしくない行動を強く批判してください。',choices:[['ともあろうものが','The respected role raises expectations that the irresponsible conduct violates.'],['ならではの','ならではの is a noun modifier emphasizing a distinctive characteristic, usually favorably.'],['にあたって','にあたって frames an occasion and does not criticize conduct unworthy of status.'],['を皮切りに','を皮切りに launches a series and does not express disappointment in a person’s role.']]},
  {prompt:'「教師ともあろうものが、質問した学生を笑うとは」と言う人の気持ちはどれですか。',choices:[['教師なら期待される態度に反するので、強く非難している。','The speaker criticizes a failure to meet expectations associated with teaching.'],['教師だから学生を笑うのが当然だと認めている。','The expression rejects, rather than approves, such behavior.'],['教師かどうかは無関係だと強調している。','The status is central to the criticism.'],['教師のユーモアを率直に褒めている。','The example conveys reproach, reinforced by 情けない, not praise.']]},
]);

lesson('n1','conduct-unbecoming','～まじき','Modify conduct or a thing that should not be permitted or is unbecoming of the named role. Formal and strongly evaluative.',['Dictionary verb + まじき + noun.','する has the traditional form すまじき as well as するまじき. The following noun is essential in this attributive pattern.'],'work','obligation','～べきではない is a general negative recommendation. ～まじき is an elevated, forceful noun modifier, often paired with ～にある to judge suitability to a role.',[
  {ja:'研究者にあるまじき行為として、データの改ざんが批判された。',en:'Falsifying data was criticized as conduct unbecoming of a researcher.'},
  {ja:'公の場で許すまじき発言だった。',en:'It was a remark that should not be tolerated in a public setting.'},
],{wrong:'研究者にあったまじき行為だ。',correct:'研究者にあるまじき行為だ。',explanation:'まじき attaches to the dictionary verb ある, not the past form あった.'},[
  {prompt:'研究者に（　）まじき行為として、データの改ざんが批判された。',choices:[['ある','あるまじき is the fixed dictionary-form modifier meaning unbecoming or unacceptable.'],['あった','The past form does not attach to まじき here.'],['あって','The て-form does not attach to this classical-style modifier.'],['あります','A polite finite ending cannot precede まじき.']]},
  {prompt:'「公の場で許すまじき発言だった」とは、発言をどう評価していますか。',choices:[['公の場では容認できない発言だった。','許すまじき modifies the remark as something that must not be tolerated.'],['公の場だから、どんな発言でも許される。','This reverses the negative normative evaluation.'],['発言を許すかどうかは、まだ一度も考えていない。','The phrase conveys a definite judgment, not suspended consideration.'],['公の場で必ず言うべき、模範的な発言だった。','The expression condemns the remark rather than recommending it.']]},
]);

lesson('n1','worthy-of','～に足る','Judge something worthy of or sufficient for the named action or evaluation. Formal written language.',['Dictionary verb + に足る + noun.','Some する-nouns can appear directly: 信頼に足る、評価に足る. Negative: ～に足りない.'],'education','evaluation','～に値する also means worthy of an evaluation. ～に足る often states whether evidence, character or content meets a sufficient standard; avoid interpreting it as physical arithmetic alone.',[
  {ja:'結論を支えるに足る資料が、まだ集まっていない。',en:'We have not yet gathered enough evidence to support the conclusion.'},
  {ja:'信頼に足る説明なら、都合の悪い情報も隠さないはずだ。',en:'A trustworthy explanation should not conceal inconvenient information either.'},
],{wrong:'結論を支えたに足る資料が必要だ。',correct:'結論を支えるに足る資料が必要だ。',explanation:'Use the dictionary form 支える before に足る when judging evidence sufficient to support the conclusion.'},[
  {prompt:'結論を支える（　）資料が、まだ集まっていない。結論を十分に裏づけられる資料という意味です。',choices:[['に足る','に足る modifies evidence as sufficient to support the conclusion.'],['をよそに','This would form a contrastive clause and cannot create the required sufficiency modifier.'],['が早いか','This describes an immediate sequence, not the evidential standard of a noun.'],['かたわらの','This does not create a modifier meaning sufficient to support a conclusion.']]},
  {prompt:'「信頼に足る説明」という評価に最も近いものはどれですか。',choices:[['信用できるだけの確かさを備えた説明。','The explanation meets a sufficient standard for trust.'],['長ければ内容を問わず信じてよい説明。','Length alone does not establish trustworthiness.'],['まだ疑わしいが、確認する必要のない説明。','This contradicts the positive standard of 信頼に足る.'],['一つの数字を足し算した説明。','足る here expresses adequacy, not adding numerical values.']]},
]);

source('reading','n2','manual-assumptions','Why a longer manual did not help','technology',
  '新しい予約端末を導入した施設で、利用者が途中で操作をやめてしまうことが多かった。担当者は説明が足りないのだと考え、注意事項を追加した。しかし、説明書が長くなるほど読む人が減り、窓口への問い合わせはかえって増えた。そこで、初めて使う人に操作してもらい、担当者は口を出さずに様子を見ることにした。\n\n観察すると、多くの人が最初の画面で迷っていた。説明書には「希望する枠を選ぶ」とあったが、枠とは時間を指すのか、部屋を指すのかが分からなかったのである。担当者にとって当然の言葉が、利用者にとっても当然とは限らない。操作に慣れた人が文章を増やしても、この違いに気づかなければ問題は解決しない。\n\n担当者は「枠」を「利用する部屋と時間」に置き換え、選択する順序に合わせて説明を並べた。細かな注意事項は、関係する画面にだけ表示した。すると、説明の総量は減ったのに、最後まで予約できる人が増えた。ただし、読む力が人によって違うため、文字を短くするだけで全員に対応できるわけではない。図や窓口での説明も残している。\n\nよい説明は、書き手が知っていることを全て並べたものではない。読み手がどこで立ち止まるかを確かめ、その場で必要な情報を渡すものである。説明を改善する出発点は、文章の量を増やすことより、相手の見え方を知ることにある。',
  'A facility introduced a new reservation terminal, but users often abandoned the process. Staff assumed the explanation was insufficient and added warnings. As the manual became longer, fewer people read it and inquiries actually increased. They then observed first-time users without intervening.\n\nMany were confused on the first screen. “Choose your preferred slot” did not make clear whether “slot” meant a time or a room. Words obvious to staff were not necessarily obvious to users. Adding text without noticing this difference would not solve the problem.\n\nStaff replaced “slot” with “the room and time you will use,” arranged the instructions in selection order, and showed detailed warnings only on relevant screens. Although the total explanation decreased, more people completed reservations. Reading ability varies, however, so shorter text alone cannot serve everyone; diagrams and help at the desk remain.\n\nGood explanations do not list everything the writer knows. They identify where readers get stuck and provide the information needed there. Improvement begins with understanding the reader’s perspective rather than increasing the amount of text.',[
  {prompt:'注意事項を追加しても、問い合わせが減らなかった主な理由は何ですか。',evidence:'担当者にとって当然の言葉が、利用者にとっても当然とは限らない。',choices:[['利用者が最初に理解できない言葉に、担当者が気づいていなかったから。','Observation exposed an unrecognized gap in the meaning of 枠; adding warnings had not addressed it.'],['利用者が部屋を予約する必要を全く感じていなかったから。','Users tried to operate the terminal; the passage does not say they had no need for reservations.'],['説明書の文字が増えるほど、必ず機械が故障するから。','No mechanical failure is described; the issue is reader understanding.'],['窓口で説明することが、初めから禁止されていたから。','Desk help is retained and is never described as prohibited.']]},
  {prompt:'筆者が説明の改善で最も重視していることはどれですか。',evidence:'読み手がどこで立ち止まるかを確かめ、その場で必要な情報を渡すものである。',questionType:'reading-thematic',choices:[['読み手が迷う点を知り、必要な場面に合う情報を示すこと。','The conclusion prioritizes understanding difficulties and delivering relevant information at the right point.'],['説明を短くすれば、ほかの対応は全て不要になること。','The passage explicitly retains diagrams and desk help because readers differ.'],['担当者が知っている情報を、最初の画面に全て載せること。','This recreates the overload the author rejects.'],['利用者が間違える前に、担当者が毎回操作を代わりに行うこと。','Observing users reveals their perspective; taking over every operation is not the proposed improvement.']]},
]);

source('reading','n2','shared-bags','A bag-lending experiment in a shopping street','community',
  '商店街では、買い物袋を持たずに来た人に、洗って繰り返し使える袋を貸すことにした。最初は、無料で貸せば利用者が増え、ごみも減るだろうと期待していた。ところが、一か月後には半分以上の袋が戻らず、店側は補充を続けるべきか迷った。袋を貸す制度そのものをやめようという意見も出た。\n\n利用した人に尋ねると、「返すつもりだったが、借りた店に行く機会がなかった」という答えが多かった。袋を借りた人が、全員同じ店で買い物を繰り返すとは限らないのである。制度を作った人は袋の便利さに注目していたが、返却のしやすさを十分に考えていなかった。\n\nそこで、商店街のどの参加店でも返せるようにした。また、貸すときに百円を預かり、返却時に返す方法を試した。百円は売り上げではなく、返すことを思い出してもらうためのお金である。返却率は上がったが、店員が説明と返金に時間を取られるという新しい負担も生まれた。\n\nこの結果を見て、商店街は制度を成功か失敗かの一言で決めつけなかった。袋が戻ることだけを評価すれば、店員の負担を見落とすからだ。利用者と店の両方が続けられる方法を探すため、貸し出し数と対応時間を記録し、三か月後に改めて判断することにした。環境によい目的でも、実際に続けられる仕組みがなければ、その効果は長く残らない。',
  'A shopping street began lending washable reusable bags to shoppers without a bag. They expected free loans to increase use and reduce rubbish, but after a month more than half had not been returned. Some suggested ending the scheme.\n\nUsers often intended to return the bags but had no reason to visit the same shop again. Designers had focused on convenience at the point of borrowing and neglected ease of return.\n\nBags could then be returned to any participating shop. A trial deposit of 100 yen, refunded on return, served as a reminder rather than revenue. Returns improved, but explaining the system and issuing refunds created another burden for staff.\n\nThe shopping street did not label the experiment simply a success or failure. Looking only at return rates would conceal staff workload. They decided to record loan numbers and service time and reassess after three months. Even an environmentally sound aim needs a workable system if its effects are to last.',[
  {prompt:'最初に袋が十分戻らなかった理由として、本文に述べられているものはどれですか。',evidence:'返すつもりだったが、借りた店に行く機会がなかった',choices:[['返却しようと思っても、借りた店に再び行く機会が少なかった。','Users’ reported intentions distinguish an inconvenient return process from deliberate refusal.'],['返したときに、百円を追加で払う必要があった。','The initial loans were free; the later deposit was refunded on return.'],['参加店は全て、洗った袋の返却を断っていた。','The passage does not mention rejecting clean returned bags.'],['袋を使うこと自体が、全ての店で禁止された。','The stores introduced bag lending, rather than prohibiting use.']]},
  {prompt:'商店街が三か月後に改めて判断するのは、なぜですか。',evidence:'袋が戻ることだけを評価すれば、店員の負担を見落とすからだ。',choices:[['返却率の改善と、店側の負担の両方を考える必要があるから。','The evaluation must include the workload as well as the improved return rate.'],['百円の売り上げを、最大にする方法だけを決めたいから。','The deposit is expressly not revenue, and the evaluation concerns sustainability.'],['環境によい目的なら、利用状況を調べる必要がないから。','The author argues that a good purpose still needs a workable mechanism and evidence.'],['返却率が上がったという事実を、認めたくないから。','The improvement is acknowledged; the issue is avoiding an incomplete assessment.']]},
]);

source('reading','n2','recorded-seminars','Two views on recording a seminar','education',
  '大学の小さなゼミで、欠席した学生のために話し合いを録画する案が出た。次の二人の意見を読んでください。\n\n【学生・森】\n仕事や家族の事情で出席できない学生もいるので、後から見られるようにしてほしい。ただ、録画を見れば参加したのと同じだとは思わない。画面では、理解できない点をその場で尋ねられないからだ。見た人が質問を送れる場所も必要だと思う。録画を残すことは、欠席を勧めるためではなく、学びを途中で止めないための方法である。\n\n【教員・坂本】\n出席できない人への配慮には賛成だ。しかし、話し合いには、まだまとまっていない考えや間違いも出てくる。後で何度も見られると思うと、学生が発言を控えるかもしれない。その場では自然に出る疑問が、記録を意識して消えてしまうなら、授業の質にも影響する。説明の部分だけを録画し、話し合いは録画せず、終わってから論点を短くまとめる方法を試してはどうか。\n\nゼミは、教員の説明だけを録画し、学生の発言は録画しないことにした。出席者がまとめた論点も共有し、欠席者からの質問には次の授業で答える。一か月後、視聴した学生の理解と、授業中の発言の変化を確かめる予定だ。欠席者の人数だけで、録画の効果を判断することはしない。二人が重視する点は違うが、単に全て録画するか、一切残さないかという選択にとどまらない案になった。',
  'A small university seminar considered recording discussions for absent students.\n\nStudent Mori: Students sometimes miss class because of work or family circumstances, so later access would help. Watching is not the same as participating because questions cannot be asked immediately. Viewers also need somewhere to submit questions. Recording should keep learning from stopping rather than encourage absence.\n\nTeacher Sakamoto: I support accommodating absentees. Discussions, however, include tentative ideas and errors. Students may speak less if they know these will be replayed. That can undermine the class. We could record only explanations, leave discussion unrecorded, and summarize its issues afterward.\n\nThe seminar adopted that approach. It shares participants’ summaries and answers absentees’ questions in the next class. After a month, it will check viewers’ understanding and changes in classroom contributions, rather than judge recording solely by absence numbers. The two priorities produced an option beyond recording everything or preserving nothing.',[
  {prompt:'森さんと坂本先生の両方が認めていることはどれですか。',evidence:'出席できない人への配慮には賛成だ。',questionType:'reading-integrated',choices:[['出席できない学生の学びを支える必要がある。','Mori seeks continued learning and Sakamoto explicitly agrees with accommodating absent students.'],['学生の発言を全て録画することが最も大切だ。','Sakamoto worries that recording student contributions will inhibit discussion.'],['録画を見れば、その場で参加したのと全く同じになる。','Mori explicitly rejects this equivalence because viewers cannot ask immediately.'],['欠席者への対応は、ゼミの質と無関係だ。','Both proposals concern learning quality, although their priorities differ.']]},
  {prompt:'ゼミが決めた方法は、坂本先生の心配にどう対応していますか。',evidence:'教員の説明だけを録画し、学生の発言は録画しないことにした。',questionType:'reading-integrated',choices:[['学生の発言を残さないことで、話し合いで考えを出しやすくする。','The selective recording addresses the concern that replayable tentative contributions discourage speech.'],['欠席した学生からの質問を、全て受け付けないようにする。','Absentees can submit questions and receive answers next class.'],['学生の間違った発言だけを録画して、後から訂正する。','No student contributions are recorded; selective preservation of errors is not proposed.'],['教員の説明を省き、学生だけで授業を進める。','The teacher’s explanations are recorded, not removed.']]},
]);

source('reading','n2','study-room-trial','Study-room trial: different ways to join','services',
  '学習室の利用者の皆さんへ\n\nこれまで夜の学習室は、毎回窓口で申し込む方式でした。しかし、仕事が終わる時間が一定でない人から、窓口が開いている間に手続きをするのは難しいという声がありました。一方、長い期間予約したまま来ない人が増えると、当日利用したい人の席がなくなります。そこで、十一月の一か月間だけ、次の二つの方式を試します。\n\n【定期利用】\n毎週同じ曜日の午後六時から八時まで、四回分の席をまとめて予約できます。希望者は十月二十五日までにオンラインで申し込んでください。申込数が席数を超えた場合は抽選です。結果は二十八日にメールで知らせます。欠席する日は、前日の午後八時までに予約画面で取り消してください。連絡なく二回欠席した場合は、残りの予約を取り消します。\n\n【当日利用】\n定期予約されていない席と、取り消された席を当日の正午に予約画面へ出します。予約できれば、窓口で事前の手続きをする必要はありません。開始から十五分過ぎても来ない場合は、ほかの方に席を開放します。\n\nどちらの方式でも、利用カードを入口の機械に通してください。カードを初めて作る方だけは、窓口が開いている平日の午前十時から午後五時に、本人確認書類を持って来てください。カード作成後は、夜もそのまま使えます。\n\n試行の後、予約数だけでなく実際の利用数も確認します。利用しやすさと、席が空いたままになる問題を両方考えて、十二月以降の方式を決めます。',
  'Notice to study-room users:\n\nNighttime access previously required a desk application every time. People with variable work finishing times found this difficult. However, long reservations left unused can deprive same-day users of seats. Two approaches will therefore be tried during November.\n\nRegular use: Reserve four weekly sessions on the same weekday from 6 to 8 p.m. Apply online by October 25. Oversubscribed places are allocated by lottery, with results emailed on October 28. Cancel absences online by 8 p.m. the preceding day. Two unnotified absences cancel the remaining bookings.\n\nSame-day use: Unreserved and canceled seats appear online at noon that day. A successful booking requires no advance desk procedure. Seats are released to others if the user has not arrived fifteen minutes after the start.\n\nBoth groups swipe their user cards at the entrance. Only first-time card applicants must visit the desk on weekdays between 10 a.m. and 5 p.m., carrying identification. Thereafter, cards work at night.\n\nAfter the trial, actual attendance as well as bookings will be checked to balance access with unused seats when choosing the system for December onward.',[
  {prompt:'利用カードをすでに持つ人が当日利用したい場合、本文に合う行動はどれですか。',evidence:'定期予約されていない席と、取り消された席を当日の正午に予約画面へ出します。',questionType:'reading-information',choices:[['当日の正午以降に空席を確認し、予約して開始時刻に来る。','Same-day places are published at noon; an existing card removes the first-time desk requirement.'],['十月二十五日までに申し込まなければ、当日利用もできない。','That deadline applies to regular use, not same-day booking.'],['カードを持っていても、毎回午後五時までに窓口で手続きをする。','Successful same-day booking needs no advance desk procedure.'],['予約した席には、開始から三十分後に来ても必ず座れる。','An unclaimed seat is released after fifteen minutes, so thirty-minute lateness is not guaranteed.']]},
  {prompt:'予約数に加えて、実際の利用数も調べるのはなぜですか。',evidence:'利用しやすさと、席が空いたままになる問題を両方考えて、十二月以降の方式を決めます。',questionType:'reading-information',choices:[['予約できる便利さだけでなく、席が実際に使われているかも評価するため。','The trial addresses both access and idle booked seats, so booking counts alone are insufficient.'],['カードを作った人の名前を、全て公開するため。','No publication of names is mentioned.'],['予約が多ければ、欠席が多くても成功と決めるため。','The notice expressly avoids relying on reservations alone.'],['十一月の利用を全て禁止し、十二月だけ開くため。','November is the trial month with both forms of use available.']]},
],'notice');

source('reading','n1','translation-fidelity','Fidelity across different forms','culture',
  '翻訳について語るとき、原文に忠実であることは当然の目標とされる。だが、その忠実さは、単語を一つずつ同じ順に置き換えることで達成できるのだろうか。言葉は、辞書に載る意味だけで働くわけではない。誰に、どの場面で、どの程度直接的に伝えるかによって、同じ表現でも果たす役割が変わる。\n\n例えば、原文で短く示された断りを、その短さまで守って別の言語に移すと、必要以上に冷淡に響く場合がある。そこで翻訳者が一言説明を補えば、文字の数は増えるが、相手への配慮という原文の働きはむしろ保たれるかもしれない。反対に、丁寧さを増やそうとして説明を重ねれば、原文にないためらいや言い訳まで生み出しかねない。したがって、形を変えることが忠実である場合もあれば、変えすぎることが不忠実になる場合もある。\n\nこのように述べると、翻訳は結局、翻訳者の好みに任されるのかという疑問が出る。しかし、唯一の置き換えがないことと、どんな置き換えも同じように認められることは別である。語り手が何をしているのか、前後の文章がどう関係しているのか、読み手にどんな受け取り方を促しているのかを、根拠を示して説明する必要がある。解釈が複数あっても、それぞれの解釈が支えられる範囲は検討できる。\n\n忠実さとは、原文の形を動かさず保存することだけではない。異なる表現環境の中で、原文が果たしていた働きを、できる限り説明可能な形で引き受けることである。翻訳の質を問うときには、どこを変えたかだけでなく、何を保つために変えたのかを問うべきだ。ただし、その説明は、訳文を読んだ人の反応によっても確かめ直されなければならない。翻訳者が意図を述べるだけで、働きが保たれたと証明できるわけではないからだ。',
  'Fidelity to the original is taken as a natural goal of translation. Yet can it be achieved by replacing words one by one in the same order? Language functions through context, audience and directness, not dictionary meanings alone.\n\nA short refusal may sound unnecessarily cold when transferred with exactly the same brevity. Adding an explanation can increase length while preserving the original consideration for the listener. Conversely, adding excessive politeness may create hesitation or excuses absent from the original. Changing form can therefore preserve fidelity, while excessive change can undermine it.\n\nThis does not leave translation entirely to personal preference. The absence of one unique replacement does not mean all replacements are equally justified. Translators should give evidence for their account of the speaker’s act, surrounding textual relationships and intended reception. Multiple interpretations can still be assessed for support.\n\nFidelity involves carrying the original’s function into a different expressive environment in an explainable way. Assessment should ask what was preserved through a change, not simply where changes occurred. Readers’ actual responses must also test the explanation: a translator’s statement of intent alone does not prove that the function was retained.',[
  {prompt:'断りに説明を一言補う例を挙げた目的は何ですか。',evidence:'文字の数は増えるが、相手への配慮という原文の働きはむしろ保たれるかもしれない。',questionType:'reading-long',choices:[['形を変えることが、原文の働きを保つ手段になり得ると示すため。','The example separates formal resemblance from preserving the refusal’s interpersonal function.'],['原文より長い翻訳は、常に優れていると証明するため。','The following contrast warns that excessive explanation can introduce meanings absent from the original.'],['断りは、どの言語でも同じ短さで自然に伝わると示すため。','The example explicitly describes a brief refusal sounding colder in another language.'],['翻訳者の意図さえ分かれば、読み手の反応は不要だと示すため。','The conclusion requires checking reception as well as the translator’s intention.']]},
  {prompt:'筆者の考える翻訳の評価に最も近いものはどれですか。',evidence:'どこを変えたかだけでなく、何を保つために変えたのかを問うべきだ。',questionType:'reading-thematic',choices:[['変更の目的を根拠から検討し、読み手への働きも確かめる。','The argument combines an explainable functional interpretation with testing actual reception.'],['単語の順番が原文と同じであれば、それだけで忠実と判断する。','The author rejects unchanged form as a sufficient measure of fidelity.'],['解釈が複数ある以上、訳の質を比較することは不可能だとする。','Multiple interpretations can still be assessed by the evidence supporting them.'],['翻訳者の好みで選んだ訳は、説明がなくても同等に認める。','The absence of a unique replacement does not justify arbitrary choice.']]},
]);

source('reading','n1','productive-uncertainty','When efficiency needs room for uncertainty','work',
  '組織の効率を高める提案では、手順の統一と時間の短縮がしばしば同時に掲げられる。すでに目的と方法が定まった作業なら、重複を取り除き、判断の基準を共有することで、確かに負担を減らせる。しかし、その成功をもって、あらゆる活動は同じ方法で効率化できると考えるのは早計である。\n\n新しい問題を発見する活動では、何が重要な問いなのか自体が、当初は明らかでない。調べる過程で前提が崩れ、別の道へ戻ることもある。この戻りを全て失敗として数えれば、担当者は確実に終えられる小さな問いだけを選ぶようになるだろう。記録上の達成率は上がるかもしれないが、組織が気づいていない問題を捉える力は弱まる。速く答えることと、答えるべき問いを見いだすことは、同じ尺度では測れない。\n\nもっとも、探索という言葉を掲げれば、進展のない活動も無期限に認められるというわけではない。何を試し、どの前提が変わり、次に何を確かめるのかは説明できるはずだ。すぐに使える成果がないことと、何も学ばれていないことを区別するためにこそ、この説明が必要になる。途中の変更を隠すより、変更の理由を共有したほうが、別の担当者も同じ袋小路を避けられる。\n\n効率を求めること自体を否定する必要はない。必要なのは、活動の性質に応じて、削るべき重複と残すべき余白を区別することだ。定型作業を速めて生まれた時間を、結論の見えない検討に回すことも、組織全体では合理的な配分になり得る。余白は成果に対する責任から逃れる場所ではなく、まだ名づけられていない問題を見つけるために、説明責任とともに確保する時間なのである。',
  'Proposals for organizational efficiency often combine standardized procedures with shorter completion times. These reduce burdens in work with established aims and methods. It is premature, however, to assume the same approach suits every activity.\n\nIn discovering new problems, the important question may itself be unclear. Investigation may overturn assumptions and require backtracking. If all such backtracking counts as failure, staff may choose only small questions they can certainly finish. Recorded completion rates could rise while the ability to identify unnoticed problems declines. Answering quickly and finding the right question cannot be measured identically.\n\nCalling an activity exploratory does not justify indefinite support without progress. Staff should explain what they tried, which assumptions changed and what they will check next. This distinguishes a lack of immediately usable results from a lack of learning. Sharing reasons for changes helps others avoid the same dead ends.\n\nEfficiency itself need not be rejected. Organizations should distinguish redundant work to remove from room for exploration to preserve. Time saved on routine tasks can reasonably fund uncertain inquiry. This room is not an escape from responsibility for results; it is time for finding unnamed problems, accompanied by accountability.',[
  {prompt:'筆者によれば、探索中に道を戻ることを全て失敗と数えると、どのような問題が生じますか。',evidence:'記録上の達成率は上がるかもしれないが、組織が気づいていない問題を捉える力は弱まる。',questionType:'reading-long',choices:[['終えやすい問いに偏り、未知の問題を発見する力が弱まる。','The evaluation encourages safe, small questions at the expense of discovering unfamiliar problems.'],['定型作業の手順が全て失われ、同じ作業ができなくなる。','The argument concerns selection of exploratory questions, not loss of all routine procedures.'],['達成率が必ず下がるため、説明責任もなくなる。','The passage allows the recorded rate to rise and retains explanation requirements.'],['試した方法を共有しなくても、ほかの人は同じ失敗を避けられる。','Sharing reasons is expressly useful in preventing repeated dead ends.']]},
  {prompt:'本文でいう「残すべき余白」に最も近いものはどれですか。',evidence:'説明責任とともに確保する時間なのである。',questionType:'reading-thematic',choices:[['試行や変更の理由を説明しながら、未知の問題を検討する時間。','The conclusion combines protected exploratory time with accountability.'],['何も学ばれなくても、無期限に続けることを保障した時間。','The author explicitly rejects indefinite activity without explainable progress.'],['定型作業の重複を、確認せず残すための時間。','The author supports removing unnecessary routine duplication.'],['成果への責任を負わず、全ての効率化を避ける時間。','The passage rejects both escape from responsibility and blanket opposition to efficiency.']]},
]);

source('reading','n1','museum-absence','Two proposals for an incomplete exhibition','culture',
  '町の資料館で、地域の暮らしを伝える展示を作り直すことになった。保存されている資料は商店や有力な家のものが多く、移り住んだ人や家で働いていた人の記録は少ない。担当者二人が、展示の方針について意見を述べた。\n\n【担当者・加藤】\n資料が多い集団ばかりを取り上げれば、それが地域の歴史全体であるかのように見えてしまう。資料が少ない人々の声を、今からでも集める必要がある。ただ、現在の聞き取りで得た話を、当時の記録と同じ種類の資料として扱うのは適切ではない。誰が、いつ、どの立場から語ったのかを示し、過去を現在から語ることの意味も伝えたい。\n\n【担当者・西】\n新しい声を集めることには賛成だが、全ての空白を埋められるわけではない。展示を整えるために、分からない点をもっともらしく補うことは避けたい。むしろ「この集団については記録が十分に残っていない」と明記することにも価値がある。何が保存されやすく、何が残りにくかったのかを来館者が考える入口になるからだ。空白は展示の欠陥として隠すだけのものではない。\n\n二人の意見を受け、資料館は、残された資料と現在の聞き取りを区別して並べることにした。十分に分からない点には、その理由を記す。展示の完成を理由に聞き取りを終えることはせず、新たな情報が得られたときに説明を改める。展示は完全な地域像を固定するものではなく、何を知り、何をまだ知らないかを、来館者と共有する場として位置づけられた。',
  'A town museum is redesigning an exhibition about local life. Surviving material mostly comes from shops and influential families; newcomers and people who worked at home left fewer records.\n\nKato: Focusing only on well-documented groups may make them appear to represent the entire history. We should collect underrepresented voices now, while distinguishing present-day interviews from contemporary records. We should specify who spoke, when and from what position, and convey what it means to narrate the past from the present.\n\nNishi: I support collecting voices, but not all gaps can be filled. We should not invent plausible content to make the display complete. Explicitly stating that records for a group are insufficient can invite visitors to consider what was easily preserved and what was not. Gaps need not be hidden merely as defects.\n\nThe museum will display surviving records and current interviews distinctly and explain uncertainties. Interviews will continue after opening, and explanations will change with new information. Rather than fixing a complete image of the town, the exhibition will share what is known and unknown with visitors.',[
  {prompt:'加藤さんと西さんの両方の考えに合う方針はどれですか。',evidence:'残された資料と現在の聞き取りを区別して並べることにした。',questionType:'reading-integrated',choices:[['新しい声を集めつつ、資料の性質と分からない点を明示する。','Kato supports new testimony with provenance; Nishi supports collection while insisting on acknowledging gaps.'],['記録の少ない集団は、地域史と無関係だとして展示から除く。','Both address the underrepresentation rather than treating the groups as irrelevant.'],['現在の聞き取りを、当時そのまま記録されたものとして示す。','Kato explicitly objects to treating the two sources as the same kind of record.'],['展示の完成後は、説明を変えないために聞き取りをやめる。','The adopted policy explicitly continues interviews and revises explanations.']]},
  {prompt:'西さんが「空白」に価値を認めるのは、なぜですか。',evidence:'何が保存されやすく、何が残りにくかったのかを来館者が考える入口になるからだ。',questionType:'reading-integrated',choices:[['記録が残る仕組みや偏りを、来館者が考える契機になるから。','The gap draws attention to the selective processes that shaped surviving historical evidence.'],['空白が多いほど、調査しなくても完全な地域史になるから。','Nishi denies completeness and supports further collection rather than avoiding research.'],['資料のない集団が存在しなかったと、証明できるから。','Absence of records is not treated as proof that people did not exist.'],['空白をもっともらしい話で埋めれば、誤解が必ずなくなるから。','Nishi specifically rejects plausible invented additions to fill gaps.']]},
]);

source('reading','n1','editorial-review','Editorial review with several ways to participate','communication',
  '共同論集の執筆者の皆様へ\n\n今回の論集では、原稿の完成度を高めるとともに、編集過程を執筆者にも分かる形にするため、相互検討を試行します。ただし、未公表の考えを他者に見せる負担や、指摘がそのまま採否の評価だと受け取られる危険にも配慮します。検討への参加と、論集への掲載審査は別の手続きです。参加を見送ったことだけを理由に、不採用にすることはありません。\n\n【参加方法】\n全文共有：原稿全文を参加者に共有し、書面で意見を受け取ります。\n要点共有：執筆者が指定した二千字以内の要旨と、検討してほしい論点のみを共有します。\n個別相談：他の執筆者には共有せず、編集担当者一人と相談します。\n\nいずれも十一月十日までに、希望する方法と、特に意見を求めたい点を編集部へお知らせください。連絡がない場合は、相互検討への参加を希望しないものとして扱います。原稿の掲載審査は予定どおり進めます。共有後の方法変更はできますが、一度共有された資料を参加者が読んだという事実は取り消せません。変更を希望する場合は、編集部にご相談ください。\n\n参加者は、受け取った原稿や要旨を外部へ転送せず、内容を引用するときは執筆者本人に確認してください。検討で出た指摘への対応は、全てを受け入れる必要はありません。ただし、修正した点と、修正しなかった主な理由を、最終原稿とともに簡潔にご提出ください。編集部は、その説明をもとに、論点が十分検討されたかを確認します。指摘の数や、受け入れた割合だけで原稿を評価することはしません。',
  'Notice to contributors to a joint collection:\n\nA trial mutual review aims to improve manuscripts and make editing understandable to authors, while considering the burden of sharing unpublished ideas and the risk that comments are mistaken for publication decisions. Review participation and selection for publication are separate; declining participation alone will not lead to rejection.\n\nFull sharing distributes the entire manuscript for written comments. Summary sharing distributes only an author-selected summary of up to 2,000 Japanese characters and the issues they want examined. Individual consultation shares nothing with other contributors and involves one editor.\n\nNotify the editorial office by November 10 of your method and requested feedback areas. Silence means declining mutual review, while publication assessment proceeds. Methods can be changed after sharing, but others having already read the materials cannot be undone. Contact the editors for changes.\n\nRecipients must not forward materials externally and should check with the author before quoting. Authors need not accept every comment, but should submit a short account of revisions and the main reasons for not revising, along with the final manuscript. Editors assess whether the issues were adequately considered, not merely the number of comments or acceptance percentage.',[
  {prompt:'他の執筆者には原稿を見せたくないが、編集者の意見は聞きたい人に最も合う行動はどれですか。',evidence:'個別相談：他の執筆者には共有せず、編集担当者一人と相談します。',questionType:'reading-information',choices:[['十一月十日までに個別相談を希望し、意見を求めたい点を知らせる。','Individual consultation meets the no-peer-sharing requirement while still providing an editor’s feedback.'],['要点共有を選べば、要旨も他の執筆者には見られないと考える。','Summary sharing does distribute the selected summary to participants.'],['何も連絡しなければ、自動的に編集者との相談が設定される。','No contact is treated as declining participation, not automatic individual consultation.'],['全文共有をしてから、読まれたという事実も取り消してもらう。','The notice explicitly says that already-read shared material cannot be unread.']]},
  {prompt:'指摘を受け入れなかった場合の対応として、本文に合うものはどれですか。',evidence:'修正した点と、修正しなかった主な理由を、最終原稿とともに簡潔にご提出ください。',questionType:'reading-information',choices:[['主な理由を説明し、最終原稿とともに提出する。','Rejection of suggestions is allowed, but the author must explain the main reasons so the issue’s consideration can be assessed.'],['指摘は全て採否の決定なので、必ず原稿から削る。','Comments are separate from publication assessment and need not all be accepted.'],['受け入れた指摘の割合だけを提出し、理由は書かない。','The editors explicitly do not evaluate acceptance percentage alone and ask for reasons.'],['相互検討を一度受けた以上、掲載審査は自動的に合格になる。','Participation and publication assessment are separate; there is no automatic acceptance.']]},
],'notice');

source('listening','n2','reply-unfinished-chart','Quick response: a partly finished revision','work',
  '課長：修正版、今日中に全部送れそうですか。\n担当者：文章の確認は終わったんですが、図に使う元のデータがまだ届いていなくて。\n課長：では、本文だけを先に送ってください。図は数字を確認してからで構いません。空いた場所に適当な数字を入れることはしないでくださいね。',
  'Manager: Can you send the whole revision today?\nStaff: I have finished checking the text, but the original data for the chart has not arrived yet.\nManager: Then send the main text first. The chart can wait until you have checked the figures. Please do not fill the space with arbitrary numbers.',[
  {prompt:'課長の最後の発言に対する担当者の返事として、最も自然なものはどれですか。',evidence:'本文だけを先に送ってください。図は数字を確認してからで構いません。',questionType:'listening-response',choices:[['承知しました。本文を先に送り、図は確認できてから送ります。','This accepts both the requested sequence and the need to verify the chart’s data.'],['では、本文も図もデータが来るまで送りません。','The manager specifically asks for the completed text first.'],['分かりました。図の数字は想像で埋めておきます。','The manager explicitly prohibits arbitrary numbers.'],['ありがとうございます。図の数字の確認はもうしなくてよいですね。','The manager explicitly requires checking the chart’s figures before sending it; this reply incorrectly removes that requirement.']]},
  {prompt:'担当者の「元のデータがまだ届いていなくて」に対し、状況を確かめる返事として最も自然なものはどれですか。',evidence:'文章の確認は終わったんですが、図に使う元のデータがまだ届いていなくて。',questionType:'listening-response',choices:[['本文は準備できていて、図だけまだ確認できないということですね。','The indirect reply distinguishes the completed text from the chart awaiting data.'],['つまり、文章もまだ一文字も書いていないんですね。','The staff explicitly says the text check is finished.'],['もう全て完成したので、確認なしで送れるんですね。','The chart’s underlying figures remain unavailable.'],['データは届いたけれど、本文をなくしたんですね。','Neither receipt of data nor loss of text is stated.']]},
]);

source('listening','n2','reply-tentative-attendance','Quick response: attendance is not yet decided','people',
  '友人Ａ：明日の集まり、来られないって聞いたけど、欠席でいい？\n友人Ｂ：欠席と決めたわけじゃないんだ。仕事が早く終われば、少し遅れてでも行きたいと思っていて。\n友人Ａ：店に人数の変更を伝えるのが、今日の夕方までなんだよね。\n友人Ｂ：それまでには仕事の見通しがつくと思うから、分かった時点で連絡するよ。',
  'Friend A: I heard you could not come tomorrow. Should I mark you absent?\nFriend B: I have not decided to miss it. If work finishes early, I would like to come even if I am a little late.\nFriend A: We have to tell the restaurant about changes in numbers by this evening.\nFriend B: I think I will know how work will go by then, so I will contact you as soon as I know.',[
  {prompt:'最後のＢの発言に対するＡの返事として、最も自然なものはどれですか。',evidence:'それまでには仕事の見通しがつくと思うから、分かった時点で連絡するよ。',questionType:'listening-response',choices:[['じゃあ、店に伝える前に、夕方までの連絡を待つね。','This respects the tentative status and the restaurant’s notification deadline.'],['じゃあ、もう欠席で確定したと店に伝えるね。','B explicitly says absence has not been decided and promises an update.'],['人数の変更は来週まで待てるから、連絡はいらないよ。','A states that the restaurant deadline is this evening, not next week.'],['明日の朝までに仕事を全部終えてくれるんだね。','B does not promise to finish work by tomorrow morning.']]},
  {prompt:'Ｂが「欠席と決めたわけじゃない」と言った直後の返事として、意味を正しく受け止めているものはどれですか。',evidence:'仕事が早く終われば、少し遅れてでも行きたいと思っていて。',questionType:'listening-response',choices:[['仕事の状況によっては、参加できるかもしれないんだね。','B leaves participation possible, conditional on work ending early.'],['参加はもう絶対に無理ということだね。','That would turn an undecided conditional possibility into certain absence.'],['仕事に関係なく、必ず開始時刻に来るんだね。','B conditions attendance on work and allows being late.'],['集まりを中止してほしいということだね。','B expresses a wish to attend, not a request to cancel the event.']]},
]);

source('listening','n2','caption-workshop','Preparing materials for a captioned workshop','education',
  '講師：明日の動画講座、映像と説明の資料は準備できましたか。\n助手：はい。動画には字幕も付けました。ただ、音が聞こえる人には文字が多すぎるかもしれません。字幕を消した版だけ流しましょうか。\n講師：いえ、字幕が必要な人もいますから、全員用には字幕付きの版を使いましょう。詳しい説明は別の資料に分ければ、画面はそれほど混みません。\n助手：では、今ある字幕は残して、画面の下の長い説明を資料に移します。\n講師：お願いします。移す前に、説明の中に操作に必要な指示が混じっていないか確かめてください。その場で押すボタンの名前は画面にも残します。資料の印刷は私が担当しますから、修正が終わったらファイルを送ってください。\n助手：分かりました。最初に画面の説明を読み直します。',
  'Instructor: Are the video and explanatory materials ready for tomorrow’s course?\nAssistant: Yes, and I added captions. People who can hear may find there is too much text. Should we show only a version without captions?\nInstructor: No, some need captions, so we will use the captioned version for everyone. Put detailed explanations in separate materials to reduce clutter.\nAssistant: I will retain the captions and move the long explanation at the bottom into the materials.\nInstructor: Before moving it, check whether necessary operating instructions are mixed in. Keep the names of buttons pressed at that point on screen too. I will print the materials; send the files after revision.\nAssistant: Understood. First I will reread the on-screen explanation.',[
  {prompt:'助手がまずすることは何ですか。',evidence:'移す前に、説明の中に操作に必要な指示が混じっていないか確かめてください。',questionType:'listening-task',choices:[['長い説明の中で、画面に残す必要のある操作指示を確かめる。','The instructor requires this check before moving text, and the assistant confirms rereading first.'],['字幕を全て消した動画を、全員用に作る。','The instructor specifically retains captions for users who need them.'],['講師の代わりに、資料を先に印刷する。','Printing is the instructor’s task and follows revision.'],['ボタンの名前も含めて、全ての文字を資料へ移す。','Necessary button names must remain visible on screen.']]},
  {prompt:'講師が選んだ方法は、どのようなものですか。',evidence:'字幕が必要な人もいますから、全員用には字幕付きの版を使いましょう。',questionType:'listening-points',choices:[['字幕と必要な操作指示を残し、詳しい説明だけ別の資料に分ける。','This balances caption accessibility with reduced screen clutter while preserving immediate instructions.'],['字幕が必要な人には、講座への参加を遠慮してもらう。','The instructor includes them through the captioned common version.'],['全員の画面を、長い説明だけに置き換える。','The video and relevant captions stay; long detail moves elsewhere.'],['印刷物だけを配り、動画は一切使わない。','The conversation keeps the captioned video as the common teaching resource.']]},
]);

source('listening','n2','queue-and-comfort','A short talk: a popular café’s waiting line','shopping',
  '店長：週末の行列が短くなれば、店の評価も上がると考えて、注文を先に聞く仕組みを入れました。確かに、席に着いてから料理が出るまでの時間は短くなりました。でも、待っている間にメニューを決めなければならず、急かされると感じるお客さんもいました。早く出すだけでは、居心地がよくなるとは限らないんですね。\nそのため今は、急いでいる方には先に注文を聞き、席についてからゆっくり選びたい方には、その方法も選んでもらっています。もちろん、二つの方法を同時に扱うのは店員には少し複雑です。そこで、注文票に印を付け、担当が替わっても希望が分かるようにしました。行列の長さだけでなく、選ぶ時間や案内の分かりやすさも見ながら、方法を調整しています。お客さんが何を大切にするかを、こちらで一つに決めないことが重要だと思います。',
  'Manager: We introduced taking orders before seating, expecting shorter weekend queues to improve our reputation. Food did arrive sooner after seating, but some customers felt rushed into choosing while waiting. Speed alone does not guarantee comfort.\n\nNow we offer advance ordering to those in a hurry and let others choose after seating. Two methods complicate staff work, so we mark order slips to preserve preferences when staff change. We adjust the system using not only queue length but also time to choose and clarity of guidance. We should not decide that every customer values the same thing.',[
  {prompt:'店長がこの話で最も伝えたいことは何ですか。',evidence:'お客さんが何を大切にするかを、こちらで一つに決めないことが重要だと思います。',questionType:'listening-outline',choices:[['速さだけを目標にせず、客によって異なる希望に対応したい。','The talk contrasts shorter serving time with comfort and concludes that priorities vary by customer.'],['行列が短ければ、客の感想を確かめる必要はない。','The manager learned that queue length alone does not show comfort.'],['選ぶ時間を全員に同じだけ与えることが、唯一の方法だ。','The solution permits two methods according to customer preference.'],['店員の仕事が複雑になるなら、注文を全て断るべきだ。','The manager uses marked slips to handle complexity rather than refusing orders.']]},
  {prompt:'注文票に印を付けるのは、何のためですか。',evidence:'担当が替わっても希望が分かるようにしました。',questionType:'listening-points',choices:[['担当する店員が替わっても、客が選んだ方法を引き継ぐため。','The markings preserve preferences across staff handovers.'],['客の名前を、店の外へ公開するため。','No public disclosure of names is mentioned.'],['料理の値段を、並んだ順に上げるため。','The markings concern the ordering method, not changing prices.'],['ゆっくり選ぶ客には、料理を出さないため。','The café expressly supports customers who prefer to choose after seating.']]},
]);

source('listening','n2','reporter-attribution','Clarifying whose opinion a report presents','communication',
  '記者：記事の見出しを「新しい広場に住民が賛成」にしようと思います。昨日の説明会で、賛成の声がありましたから。\n編集者：何人に聞いたんですか。\n記者：説明会の後で残っていた四人です。反対する人には会いませんでした。\n編集者：それでは、住民全体が賛成しているような見出しは強すぎますね。賛成する声があったことと、全体の意見が分かったことは違います。\n記者：では、「説明会の参加者から期待の声」にして、本文には四人に聞いたと書きます。\n編集者：そのほうが範囲は正確です。ただ、期待の理由も添えてください。広場ができること自体を喜んだのか、子供の遊び場が増える点を評価したのかで、意味が変わります。\n記者：二人は子供の場所、ほかの二人は休憩できる場所に期待していました。理由を分けて書きます。',
  'Reporter: I propose the headline “Residents support the new square,” because I heard supportive voices at yesterday’s briefing.\nEditor: How many did you ask?\nReporter: Four people who stayed afterward. I did not meet opponents.\nEditor: That headline makes the whole community seem supportive. Hearing some favorable views differs from knowing the overall view.\nReporter: I will use “Briefing participants express hopes” and say in the article that I interviewed four people.\nEditor: That scope is more accurate. Add the reasons too: welcoming a square in general differs from valuing more play space for children.\nReporter: Two hoped for a place for children, and the other two for a place to rest. I will distinguish those reasons.',[
  {prompt:'最初の見出しについて、編集者が問題にした点は何ですか。',evidence:'賛成する声があったことと、全体の意見が分かったことは違います。',questionType:'listening-points',choices:[['限られた人の意見を、住民全体の意見のように見せている点。','The four interviewees support a limited attribution, not a claim about all residents.'],['広場について、誰も賛成していなかった点。','There were favorable voices; the issue is their representativeness.'],['見出しに、子供という言葉を必ず入れていない点だけ。','The main objection is scope; reasons are a further refinement.'],['説明会を、実際には行っていなかった点。','The briefing took place; no fabrication of the event is claimed.']]},
  {prompt:'記者は本文をどのように書くことにしましたか。',evidence:'二人は子供の場所、ほかの二人は休憩できる場所に期待していました。理由を分けて書きます。',questionType:'listening-task',choices:[['聞いた人数を示し、期待する理由を二つに分けて書く。','The reporter agrees both to specify four interviewees and to distinguish their reasons.'],['四人の意見を、全員が子供の遊び場だけを望んだとまとめる。','Two wanted resting space, so this would misrepresent their reasons.'],['反対意見が必ず多数だと、根拠なしに書く。','The editor calls for accurate scope, not an unsupported opposite conclusion.'],['人数も理由も省いて、最初の見出しをそのまま使う。','The reporter accepts a narrower headline and fuller attribution.']]},
]);

source('listening','n2','evening-venue','Choosing a room without losing discussion time','community',
  '司会：夜の読書会の会場を決めましょう。十二人の予定ですが、二人は仕事の後なので七時でないと着けません。全員で一時間は話せるようにしたいです。\n担当Ａ：駅前の会議室なら六時半から九時まで使えます。ただ、飲み物を持ち込めません。図書館の部屋は無料ですが、七時半に閉まります。\n担当Ｂ：飲み物より、全員で話せる時間を優先しましょう。もう一つ、喫茶店の奥の部屋もありますね。\n担当Ａ：そこは八時半まで使えて、飲み物も出ます。ただ、十人までなので、十二人では入りません。\n司会：では駅前の会議室にしましょう。開始は七時、終了は八時半とし、早く来られる人は六時半から準備をお願いします。\n担当Ｂ：分かりました。案内には、飲み物は持ち込めないことと、全員の話し合いは七時からだということを明記します。早く来た人だけで先に議論を始めないようにしましょう。',
  'Facilitator: We expect twelve people at the evening book group. Two cannot arrive until seven after work. I want everyone to have at least an hour to discuss together.\nStaff A: The station meeting room is available 6:30–9, but no outside drinks. The library room is free but closes at 7:30.\nStaff B: Shared discussion time matters more than drinks. What about the café’s back room?\nStaff A: It is available until 8:30 with drinks, but it holds only ten.\nFacilitator: We will choose the station room, discuss from seven to 8:30, and have those available prepare from 6:30.\nStaff B: The notice will specify no outside drinks and a seven o’clock start for everyone’s discussion. Early arrivals should not begin the discussion alone.',[
  {prompt:'駅前の会議室を選んだ理由として、最も適切なものはどれですか。',evidence:'全員で話せる時間を優先しましょう。',questionType:'listening-integrated',choices:[['十二人が入れ、七時以降も全員で一時間以上話せるから。','It meets capacity and discussion-time constraints; the library closes too soon and the café is too small.'],['無料で、飲み物も自由に持ち込めるから。','The library is the free room; the station room forbids outside drinks.'],['仕事の後の二人を、参加者から外せるから。','The facilitator prioritizes including everyone, including the two later arrivals.'],['十人以下に人数を減らすことが、最初から決まっていたから。','Twelve are expected and no reduction is decided.']]},
  {prompt:'六時半に来られる人は、何をすることになりましたか。',evidence:'早く来られる人は六時半から準備をお願いします。',questionType:'listening-task',choices:[['準備を行い、全員の話し合いは七時から始める。','Early arrival is for setup; the facilitator reserves discussion for all participants at seven.'],['七時に来る二人の代わりに、結論を先に決める。','The final exchange explicitly avoids early arrivals beginning discussion without the others.'],['図書館に行き、七時半まで別の読書会を開く。','The group has selected the station meeting room, not a separate library event.'],['飲み物を会議室に持ち込み、全員分を用意する。','Outside drinks are not permitted in the chosen room.']]},
]);

source('listening','n1','reply-qualified-recommendation','Quick response: support without a promise','communication',
  '編集担当：この原稿、掲載する方向で著者に伝えてもいいでしょうか。\n委員：問題設定に意義があることは認めます。ただ、結論を支える資料の弱さを、その意義で埋められるわけではありません。掲載を約束する前に、追加資料で何が確かめられるかを著者に聞いてください。\n編集担当：意義は評価しているが、掲載については確認後の判断ということですね。\n委員：ええ。その区別が伝わるようにお願いします。',
  'Editor: May I tell the author we are moving toward publication?\nCommittee member: I recognize the importance of the question. But that cannot compensate for weak evidence supporting the conclusion. Before promising publication, ask what could be checked using additional materials.\nEditor: So we value the question, but the publication decision comes after verification.\nCommittee member: Yes. Please make that distinction clear.',[
  {prompt:'最後の委員の発言に対する返事として、最も自然なものはどれですか。',evidence:'意義は評価しているが、掲載については確認後の判断ということですね。',questionType:'listening-response',choices:[['承知しました。意義への評価と採否を分け、追加資料について尋ねます。','This accepts the distinction and the concrete request without making an unsupported promise.'],['では、意義があるので掲載は確定したと伝えます。','The committee explicitly withholds a publication promise pending verification.'],['資料の弱さには触れず、著者を安心させることだけを優先します。','The committee’s requested inquiry concerns that weakness.'],['分かりました。問題設定にも価値がないと伝えます。','The committee explicitly recognizes the question’s significance.']]},
  {prompt:'編集担当が著者に伝える言葉として、会話の趣旨に最も合うものはどれですか。',evidence:'掲載を約束する前に、追加資料で何が確かめられるかを著者に聞いてください。',questionType:'listening-response',choices:[['問題設定は評価されています。結論の裏づけについて、追加資料をご相談できますか。','This conveys positive evaluation while requesting evidence without promising acceptance.'],['採用は決まっていますので、裏づけは不要です。','Neither acceptance nor elimination of the evidence requirement is authorized.'],['追加資料を一枚出せば、内容に関係なく掲載します。','The conversation specifies checking what the materials establish, not a document-count guarantee.'],['掲載の検討はしませんが、原稿を全て書き直してください。','No outright rejection or requirement to rewrite everything is stated.']]},
]);

source('listening','n1','reply-recording-dissent','Quick response: making a decision with dissent','work',
  '司会：意見が割れたままですが、今日決める必要はあります。多数決で決めて、異論は議事録から省いてもいいですか。\n参加者：決めること自体に反対しているわけではありません。ただ、少数だったというだけで懸念まで消すのはどうでしょう。試行後に何を見直すか、その懸念を手がかりに決めておいたほうがよいと思います。\n司会：採決は行いつつ、懸念も残すということですか。\n参加者：ええ、決定と検討の終了を同じことにしなければよいのです。',
  'Chair: We disagree, but a decision is needed today. Can we decide by majority vote and omit dissent from the minutes?\nParticipant: I am not against deciding. But should concerns disappear merely because they were held by a minority? They should guide what we review after the trial.\nChair: So we vote but retain the concerns?\nParticipant: Yes, as long as making a decision does not mean ending examination.',[
  {prompt:'最後の発言に対する司会の返事として、最も自然なものはどれですか。',evidence:'決定と検討の終了を同じことにしなければよいのです。',questionType:'listening-response',choices:[['では、採決後も懸念を記録し、試行で確かめる点を決めておきましょう。','This proceeds with a decision while preserving the issues for review.'],['では、少数の意見はなかったことにして、検討を終えましょう。','This is precisely the equivalence between decision and ending examination that the participant rejects.'],['全員が賛成するまで、どんな決定も永遠にできませんね。','The participant explicitly says they do not oppose making a decision now.'],['反対意見があるので、今日の決定は必ず取り消します。','Retaining concerns does not require canceling today’s vote or decision.']]},
  {prompt:'「決めること自体に反対しているわけではありません」を受けた確認として、最も適切なものはどれですか。',evidence:'試行後に何を見直すか、その懸念を手がかりに決めておいたほうがよいと思います。',questionType:'listening-response',choices:[['決定は進めてよいが、懸念を後の検証に生かしたいのですね。','The distinction permits a decision while preserving minority concerns as review criteria.'],['少数意見がある以上、採決そのものを禁止したいのですね。','The participant denies being opposed to deciding itself.'],['懸念は、決定した瞬間に全て解決するという意味ですね。','The proposed later review presupposes unresolved concerns.'],['多数の賛成を、少数の反対として記録したいのですね。','There is no proposal to misrecord votes; the concern is retaining reasons.']]},
]);

source('listening','n1','author-revision','A revision that narrows a claim','education',
  '指導教員：原稿の結論は魅力的ですが、引用した文章の役割が整理されていませんね。\n学生：引用を短くして、読みやすくすればよいでしょうか。\n指導教員：長さだけの問題ではありません。ある筆者の理想として述べられたことを、現実にそうなっている証拠のように使っています。\n学生：では、その引用を全て削除しますか。\n指導教員：残して構いません。ただ、理想を示す資料と、実態を示す資料を分けてください。実態の資料が足りないなら、現在の状況についての断定を弱める必要があります。逆に、主張に合う数字を探して後から足すだけでは、確認にはなりません。\n学生：まず、それぞれの引用が何を示すのか分類します。そのうえで、結論が資料の範囲を超えていないか見直します。\n指導教員：そうしてください。追加の調査が必要かどうかも、その後で相談しましょう。',
  'Supervisor: The conclusion is appealing, but the roles of the quoted texts are not organized.\nStudent: Should I shorten the quotations for readability?\nSupervisor: Length is not the only issue. You use one author’s ideal as if it were evidence of actual conditions.\nStudent: Should I delete all those quotations?\nSupervisor: They can stay, but distinguish evidence of ideals from evidence of reality. If actual-condition evidence is lacking, weaken categorical statements about the current situation. Merely adding figures that fit the claim is not verification.\nStudent: First I will classify what each quotation shows, then check whether the conclusion goes beyond the evidence.\nSupervisor: Yes. After that we can discuss whether further investigation is needed.',[
  {prompt:'学生がまず行うべきことは何ですか。',evidence:'まず、それぞれの引用が何を示すのか分類します。',questionType:'listening-task',choices:[['引用が理想を示すのか実態を示すのか、その役割を分類する。','The first agreed step is classification of evidential roles before reviewing the conclusion or proposing new research.'],['主張に合う数字だけを探して、結論を先に強める。','The supervisor explicitly says cherry-picking matching figures is not verification.'],['全ての引用を削り、資料のない結論だけを残す。','The supervisor allows quotations to remain with appropriate distinctions.'],['文章の長さだけを半分にし、断定の内容は変えない。','The issue is the role and sufficiency of evidence, not length alone.']]},
  {prompt:'指導教員が、実態の資料が足りない場合に求めていることは何ですか。',evidence:'現在の状況についての断定を弱める必要があります。',questionType:'listening-points',choices:[['資料から言える範囲に合わせ、現在の状況についての言い方を限定する。','The claim’s strength should match evidence rather than treating an ideal as observed reality.'],['理想として書かれた文章を、実態の証拠と呼び替える。','This is the original misuse the supervisor identifies.'],['資料が足りなくても、結論が魅力的なら断定を維持する。','The supervisor separates appeal from evidential support.'],['追加調査は必ず不要だと、今すぐ決める。','Whether further research is needed will be discussed after classification and review.']]},
]);

source('listening','n1','expertise-questions','A lecture: expertise can sharpen questions','education',
  '講演者：専門知識が増えれば、質問が減ると思われることがあります。初歩的な疑問が解消するという意味では、その通りでしょう。しかし、知識のないときには見えなかった違いが見えるために、新たな疑問が生じることもあります。例えば、同じ結果を示す二つの調査を、初心者は同じ結論だと受け取るかもしれません。方法を知る人なら、対象や測り方の違いに注目し、本当に同じことを言っているのかと尋ねます。\n専門家の役割を、いつでも断定的に答えることだけと捉えると、この働きを見落とします。もちろん、疑問を増やすだけで判断を先送りし続けるのも適切ではありません。今の資料で決められる点と、追加の確認が必要な点を区別して示す必要があります。分からないことを具体的に述べられるのは、何も知らないからとは限りません。何を確かめれば判断が変わるのかまで示せるなら、その疑問は知識を行動につなげる道具になります。答えの強さだけでなく、問いの精度にも専門性は表れるのです。',
  'Lecturer: More expertise may seem to mean fewer questions. It does resolve elementary doubts, but it also reveals distinctions previously invisible and generates new questions. Beginners may treat two surveys with the same results as equivalent. Someone who knows the methods asks whether differences in populations and measurements mean they are really saying the same thing.\n\nReducing an expert’s role to categorical answers overlooks this function. Yet multiplying doubts to postpone judgment indefinitely is also inappropriate. Experts must distinguish what can be decided now from what requires further checking. A precise account of what remains unknown can reflect knowledge. If it identifies what verification would change a judgment, the question connects knowledge with action. Expertise appears in the precision of questions as well as the strength of answers.',[
  {prompt:'講演者の主張に最も近いものはどれですか。',evidence:'答えの強さだけでなく、問いの精度にも専門性は表れるのです。',questionType:'listening-outline',choices:[['専門性は、根拠に応じた判断や、必要な確認を明確にする問いにも表れる。','The lecture joins precise questioning with identifying what is decidable and what evidence could change it.'],['専門家なら、どの問題にも即座に断定できなければならない。','The lecture rejects categorical answers as the sole definition of expertise.'],['疑問が増える人は、知識を全く身につけていない。','Knowledge can reveal new distinctions and generate informed questions.'],['判断を永久に先送りすることが、専門家の最も重要な仕事だ。','The lecturer expressly rejects indefinite postponement.']]},
  {prompt:'二つの調査の例で、専門知識のある人が注目するのは何ですか。',evidence:'対象や測り方の違いに注目し、本当に同じことを言っているのかと尋ねます。',questionType:'listening-points',choices:[['同じ結果に見えても、対象や方法の違いで意味が異なる可能性。','Knowledge of methodology prompts checking comparability rather than equating matching results.'],['同じ数字なら、方法を問わず必ず同じ意味であること。','This is the unexamined beginner inference the example contrasts with expertise.'],['数字の色が違えば、どちらの調査も無効になること。','No visual-color criterion is mentioned.'],['追加の確認が必要なら、今ある資料は全て捨てること。','The lecture distinguishes usable current knowledge from unresolved issues; it does not recommend discarding all evidence.']]},
]);

source('listening','n1','method-and-consent','Separating support for an aim from consent to a method','community',
  '代表：地域の記録を残す活動には、皆さん賛成してくださいました。来週から家の中も撮影してよいということで進めますね。\n住民：ちょっと待ってください。記録を残す目的には賛成ですが、家の中の撮影まで承諾したつもりはありません。\n代表：目的に賛成でも、方法は別ということですか。\n住民：ええ。外観なら構いませんし、古い写真をこちらで選んで提供することもできます。ただ、室内をどこまで見せるかは、家族とも相談したいです。\n記録担当：では、外観撮影と写真の提供を先に進め、室内撮影は希望する人だけに説明して、範囲を確認するのはどうでしょう。\n住民：それなら話し合えます。撮影しないと決めた人も、活動に反対だと扱われないことが大切です。\n代表：分かりました。参加の仕方を一つにせず、それぞれが選べる案内に直します。',
  'Representative: Everyone supported preserving local records, so we will proceed with photographing inside homes next week.\nResident: Wait. I support the aim, but I did not consent to indoor photography.\nRepresentative: Support for the aim differs from approval of the method?\nResident: Yes. Exterior photographs are fine, and I can select old photographs to contribute. I want to consult my family about how much of the interior to show.\nDocumentation staff: We could proceed with exterior shots and offered photos first, and explain indoor photography only to interested residents, checking the scope.\nResident: We can discuss that. People who decline photography must not be treated as opposing the project.\nRepresentative: I will revise the notice to offer different ways to participate.',[
  {prompt:'住民が最初に異議を述べた理由は何ですか。',evidence:'記録を残す目的には賛成ですが、家の中の撮影まで承諾したつもりはありません。',questionType:'listening-points',choices:[['目的への賛成を、具体的な撮影方法への承諾と同一視されたから。','The resident supports preservation but denies having authorized indoor photography.'],['地域の記録は、どんな方法でも一切残してほしくないから。','The resident permits exterior shots and selected old photographs.'],['古い写真の提供を、必ず禁止したいから。','The resident expressly offers to select and contribute old photographs.'],['他の家族の意見を聞く時間が、もう全く不要になったから。','The resident says they want to consult the family about indoor access.']]},
  {prompt:'代表が最終的に直すことにした案内は、どのようなものですか。',evidence:'参加の仕方を一つにせず、それぞれが選べる案内に直します。',questionType:'listening-task',choices:[['撮影や写真提供など、希望に応じて参加方法を選べるもの。','The revised notice separates participation in the aim from consent to one imposed method.'],['活動に賛成した人全員の家を、確認せず室内まで撮影するもの。','This is the assumption challenged at the start and abandoned at the end.'],['室内撮影を断った人を、活動への反対者として公表するもの。','The resident explicitly asks that refusal of a method not be equated with opposition.'],['外観撮影も写真提供も中止し、説明だけで終えるもの。','The documentation staff proposes proceeding with the accepted methods.']]},
]);

source('listening','n1','repair-project-options','Choosing a trial that keeps later options open','work',
  '責任者：古い作業机を直す計画ですが、見た目をそろえる案と、各部署の使い方に合わせる案が出ています。今期の予算では全部を一度に直すのは難しいですね。\n担当Ａ：同じ仕様で一括発注すれば、一台当たりの費用は下がります。ただ、細かな使い方の違いには対応できません。\n担当Ｂ：全部を個別に設計すると費用が上がります。まず二つの部署で違う方法を試して、使い勝手と修理の手間を比べる案なら、今期の予算でできます。\n責任者：試した机だけ特別な道具が必要になると、後で管理が難しくなりませんか。\n担当Ｂ：共通の部品で高さや棚の位置を変えれば、道具はそろえられます。結果に応じて、次の部署へ広げるか判断できます。\n担当Ａ：では、今は全体の仕様を固定せず、二部署で試行しましょう。ただ、来年の予算を考えるため、今期中に比較結果をまとめる必要があります。\n責任者：賛成です。見た目の統一だけではなく、実際の作業と維持費も比較してください。試行を選ぶのは決断を避けるためではなく、後の選択に必要な情報を得るためです。',
  'Manager: We have proposals either to give old work desks a uniform appearance or adapt them to each department. This term’s budget cannot repair them all at once.\nStaff A: A common bulk order reduces unit cost but cannot accommodate differing uses.\nStaff B: Custom design for every desk raises costs. Within this budget, two departments can trial different methods and compare usability and repair effort.\nManager: Would special tools for the trial make later management difficult?\nStaff B: Common components can change heights and shelf positions while using the same tools. Results can guide expansion to other departments.\nStaff A: Let us trial two departments without fixing a uniform specification now, but report the comparison this term for next year’s budget.\nManager: Agreed. Compare actual work and maintenance costs as well as appearance. The trial is for gathering information for later choices, not avoiding a decision.',[
  {prompt:'最終的に選ばれた案は、どの条件を満たしていますか。',evidence:'共通の部品で高さや棚の位置を変えれば、道具はそろえられます。',questionType:'listening-integrated',choices:[['今期の予算内で二部署を試し、共通の道具を使いながら違う使い方を比較する。','The agreed trial combines budget feasibility, shared tools and learning about departmental variation.'],['今期中に全部の机を個別設計し、維持費の比較はしない。','Individual design for all desks exceeds the budget; maintenance costs are explicitly part of the comparison.'],['同じ見た目を今すぐ全体に固定し、使い方の違いは無視する。','The final plan deliberately avoids fixing the overall specification before evidence is gathered.'],['特殊な道具を部署ごとに買い、結果の報告期限も設けない。','Common tools and a report within the current term are both agreed.']]},
  {prompt:'責任者が試行を選んだ目的として述べていることは何ですか。',evidence:'後の選択に必要な情報を得るためです。',questionType:'listening-outline',choices:[['実際の使い方と維持費を確かめ、後の拡大判断に役立てること。','The trial provides decision-relevant evidence rather than simply delaying commitment.'],['決定を永久に先送りし、予算について考えなくて済むようにすること。','The manager explicitly rejects avoidance, and a current-term report informs next year’s budget.'],['二部署だけを直すと、ほかの部署を今後も修理しないと決めること。','The result may guide later expansion; permanent exclusion is not decided.'],['見た目さえそろえば、作業への影響を一切調べないこと。','The manager explicitly requests comparisons of work and upkeep beyond appearance.']]},
]);
